// ─── CMMI 5-level scoring ─────────────────────────────────────────────────────
var CMMI_LEVELS = [
  {min:0,  max:19,  level:1, name:"Initial",                   short:"L1",
   desc:"Ad hoc, unpredictable. Controls are undefined or inconsistently applied.",
   color:"#EF4545", bg:"#EF454514"},
  {min:20, max:39,  level:2, name:"Managed",                   short:"L2",
   desc:"Reactive. Some controls documented and applied at a project level.",
   color:"#F59E0B", bg:"#F59E0B14"},
  {min:40, max:59,  level:3, name:"Defined",                   short:"L3",
   desc:"Proactive. Controls standardized and documented at the organization level.",
   color:"#F5A623", bg:"#F5A62314"},
  {min:60, max:79,  level:4, name:"Quantitatively Managed",    short:"L4",
   desc:"Measured. Controls monitored with quantitative metrics and managed proactively.",
   color:"#3B9EFF", bg:"#3B9EFF14"},
  {min:80, max:100, level:5, name:"Optimizing",                short:"L5",
   desc:"Continuous improvement. Controls optimized through innovation and proactive adjustment.",
   color:"#0FBB80", bg:"#0FBB8014"},
];

function cmmi(s) {
  if (s===null||s===undefined) { return CMMI_LEVELS[0]; }
  var n = Math.round(s);
  for (var i=0;i<CMMI_LEVELS.length;i++) {
    if (n>=CMMI_LEVELS[i].min&&n<=CMMI_LEVELS[i].max) { return CMMI_LEVELS[i]; }
  }
  return n>=80?CMMI_LEVELS[4]:CMMI_LEVELS[0];
}

function CmmiBadge(props) {
  var score=props.score; var size=props.size||"md";
  var c=cmmi(score);
  var fSz = size==="sm"?9:size==="lg"?13:11;
  var padding = size==="sm"?"1px 6px":size==="lg"?"4px 12px":"2px 8px";
  return (
    <span style={{color:c.color,fontSize:fSz,fontWeight:800,
      background:c.bg,borderRadius:5,padding:padding,
      display:"inline-flex",gap:4,alignItems:"center",flexShrink:0,whiteSpace:"nowrap"}}>
      {c.short} — {c.name}
    </span>
  );
}

function CmmiBar(props) {
  var score=props.score; var width=props.width||200;
  var c=cmmi(score);
  return (
    <div style={{width:width,display:"inline-block"}}>
      <div style={{height:6,background:"#1a2030",borderRadius:3,overflow:"hidden",
        display:"flex",marginBottom:3}}>
        {CMMI_LEVELS.map(function(lvl,i){
          var active=cmmi(score).level===lvl.level;
          return (
            <div key={i} style={{flex:1,height:"100%",
              background:active?lvl.color:"transparent",
              borderRight:i<4?"1px solid #2a3040":""}}/>
          );
        })}
      </div>
      <div style={{display:"flex",justifyContent:"space-between"}}>
        {CMMI_LEVELS.map(function(lvl,i){
          var active=cmmi(score).level===lvl.level;
          return (
            <div key={i} style={{fontSize:7,color:active?lvl.color:"#3a4050",
              fontWeight:active?800:400,textAlign:"center",width:"20%"}}>
              L{lvl.level}
            </div>
          );
        })}
      </div>
    </div>
  );
}
function hl(s) { return s>=80?"Healthy":s>=60?"At Risk":"Critical"; }
function fmtD(n) {
  if (!n || n===0) { return "$0"; }
  if (n>=1e9) { return "$"+(n/1e9).toFixed(1)+" billion"; }
  if (n>=1e6) { return "$"+Math.round(n/1e6)+" million"; }
  return "$"+Math.round(n/1e3)+"K";
}
function fmtNum(n) { if(!n){return "0";} if(n>=1e6){return (n/1e6).toFixed(1).replace(/\.0$/,"")+"M";} if(n>=1e3){return (n/1e3).toFixed(0)+"K";} return String(Math.round(n)); }
function fmtExp(m) {
  // m is in $M. Format as B or M clearly.
  if (!m && m!==0) { return "$0"; }
  if (m >= 1000) { return "$"+(m/1000).toFixed(m%1000===0?0:1)+"B"; }
  if (m >= 100)  { return "$"+Math.round(m)+"M"; }
  if (m >= 10)   { return "$"+m.toFixed(1)+"M"; }
  return "$"+m.toFixed(1)+"M";
}
function fmtDS(n) {
  if (!n || n===0) { return "$0"; }
  if (n>=1e9) { return "$"+(n/1e9).toFixed(1)+"B"; }
  if (n>=1e6) { return "$"+Math.round(n/1e6)+"M"; }
  return "$"+Math.round(n/1e3)+"K";
}
function nameFromEmail(e) {
  if (!e) { return ""; }
  var parts = e.split("@")[0].split(".");
  return parts.map(function(p){ return p.charAt(0).toUpperCase()+p.slice(1); }).join(" ");
}

