function mkT(b) {
  return Array.from({length:90}, function(_,i){
    return Math.round(Math.max(45, Math.min(95, b + Math.sin(i*0.22)*5 + Math.cos(i*0.08)*3 + (i>65?(i-65)*0.07:0))));
  });
}
