// ── AUDITABLE SCORE CALCULATION FRAMEWORK ─────────────────────────────────────
// All security scores use the SAME standardized formula for consistency.
//
// OVERALL SECURITY SCORE FORMULA (100 points total):
//   MFA Adoption Rate (weighted 15%)          -> mfaPct
//   EDR Coverage (weighted 15%)                 -> edrPct
//   SIEM Log Retention (weighted 12%)          -> siemDays (vs 90-day target)
//   Phishing Click Rate (weighted 13%)         -> phishingPct (inverted, vs 3% target)
//   Patch Compliance (weighted 15%)            -> patchPct
//   Mean Time to Detect (weighted 8%)           -> mttdHrs (vs 24-hr target)
//   Mean Time to Respond (weighted 7%)          -> mttrHrs (vs 4-hr target)
//   Security Training (weighted 7%)             -> trainingPct
//   PAM Coverage (weighted 8%)                  -> pamPct
//
// PROCESS SCORE FORMULA (65% app health + 35% global metrics):
//   App Health (65%): Based on app risk level, compliance status, gaps
//   Global Metrics (35%): Same 9 metrics as overall score, equally weighted
//
// Usage:
//   calculateOverallScore(metrics) -> returns overall security score (0-100)
//   calculateProcessScore(proc, metrics) -> returns process score (0-100)

function calculateOverallScore(m) {
  // Extract metrics with defaults
  var mfa   = m.mfaPct      != null ? +m.mfaPct      : 78;
  var edr   = m.edrPct      != null ? +m.edrPct      : 71;
  var siem  = m.siemDays    != null ? +m.siemDays    : 14;
  var phish = m.phishingPct != null ? +m.phishingPct : 9.2;
  var patch = m.patchPct    != null ? +m.patchPct    : 63;
  var mttd  = m.mttdHrs     != null ? +m.mttdHrs     : 47;
  var mttr  = m.mttrHrs     != null ? +m.mttrHrs     : 6.8;
  var train = m.trainingPct != null ? +m.trainingPct : 71;
  var pam   = m.pamPct      != null ? +m.pamPct      : 43;

  // Calculate weighted score (100 points total)
  var score =
    (mfa * 0.15) +                                                    // MFA: 15%
    (edr * 0.15) +                                                    // EDR: 15%
    (Math.min(100, siem / 90 * 100) * 0.12) +                        // SIEM: 12% (90-day target)
    (Math.max(0, 100 - phish * 5) * 0.13) +                          // Phishing: 13% (inverted, 3% target)
    (patch * 0.15) +                                                  // Patch: 15%
    (Math.max(0, 100 - (mttd - 24) * 2) * 0.08) +                    // MTTD: 8% (24-hr target)
    (Math.max(0, 100 - (mttr - 4) * 10) * 0.07) +                    // MTTR: 7% (4-hr target)
    (train * 0.07) +                                                  // Training: 7%
    (pam * 0.08);                                                     // PAM: 8%

  return Math.min(100, Math.max(0, Math.round(score)));
}

function calculateProcessScore(proc, m) {
  m = m || {};

  // Global security metrics baseline (35% of process score)
  // Uses same metrics as overall score, equally weighted (~3.89% each)
  var mfa   = m.mfaPct      != null ? +m.mfaPct      : 78;
  var edr   = m.edrPct      != null ? +m.edrPct      : 71;
  var siem  = m.siemDays    != null ? +m.siemDays    : 14;
  var phish = m.phishingPct != null ? +m.phishingPct : 9.2;
  var patch = m.patchPct    != null ? +m.patchPct    : 63;
  var mttd  = m.mttdHrs     != null ? +m.mttdHrs     : 47;
  var mttr  = m.mttrHrs     != null ? +m.mttrHrs     : 6.8;
  var train = m.trainingPct != null ? +m.trainingPct : 71;
  var pam   = m.pamPct      != null ? +m.pamPct      : 43;

  var metricsBase = Math.round(
    (mfa * 0.15) + (edr * 0.15) + (Math.min(100, siem / 90 * 100) * 0.12) +
    (Math.max(0, 100 - phish * 5) * 0.13) + (patch * 0.15) +
    (Math.max(0, 100 - (mttd - 24) * 2) * 0.08) + (Math.max(0, 100 - (mttr - 4) * 10) * 0.07) +
    (train * 0.07) + (pam * 0.08)
  );

  var apps = (proc && proc.apps) || [];
  if (apps.length === 0) {
    // No apps mapped — use the process's original score if available, otherwise metrics-only score
    var originalScore = proc.score || null;
    if (originalScore !== null) {
      return originalScore;
    }
    // Fallback to metrics-only score
    return Math.max(35, Math.min(95, metricsBase));
  }

  // Per-app health: penalise risk level, compliance failures, open gaps (65% of process score)
  var totalPenalty = 0;
  apps.forEach(function(app) {
    var p = 0;
    if (app.risk === 'Critical')     p += 18;
    else if (app.risk === 'High')    p += 9;
    else if (app.risk === 'Med')     p += 3;
    var regVals = Object.values(app.regs || {});
    regVals.forEach(function(v) {
      if (v === 'Fail')    p += 7;
      else if (v === 'Partial') p += 1.5;
    });
    if (app.gap) p += 4;
    totalPenalty += p;
  });
  var avgPenalty   = totalPenalty / apps.length;        // avg penalty per app
  var appHealthPct = Math.max(0, 100 - avgPenalty);    // 0-100 app health

  // Blend 65% app health + 35% global metrics
  return Math.max(35, Math.min(95, Math.round(appHealthPct * 0.65 + metricsBase * 0.35)));
}

// Legacy alias for backward compatibility
function computeProcScore(proc, m) {
  return calculateProcessScore(proc, m);
}

// ── Live Compliance Control Score Formula ────────────────────────────────────
// Replaces all 199 hardcoded score: values in COMPLIANCE_REPORTS.
// Anchored to the static baseline; adjusted ±by relevant security metrics
// and penalised for linked open findings.
//
// Metric selection by control name/ref keywords:
//   Access / MFA / Identity / Privileged → mfaPct + pamPct
//   Audit / Log / Retention / SIEM       → siemDays (vs 90-day threshold)
//   Training / Awareness / Workforce     → trainingPct
//   Patch / Vulnerability / CVE          → patchPct + vulnSLApct
//   Incident / Response / Recovery / MTTR→ mttrHrs (vs 4-hr threshold)
//   Detect / Monitor / SOC / MTTD        → mttdHrs (vs 24-hr threshold)
//   Endpoint / EDR / Malware             → edrPct
//   Generic / Supply Chain / Policy      → weighted average of all 6
function computeComplianceScore(ctrl, metrics) {
  var m = metrics || {};
  var mfa   = m.mfaPct      != null ? +m.mfaPct      : 78;
  var edr   = m.edrPct      != null ? +m.edrPct      : 71;
  var patch = m.patchPct    != null ? +m.patchPct    : 63;
  var train = m.trainingPct != null ? +m.trainingPct : 71;
  var pam   = m.pamPct      != null ? +m.pamPct      : 45;
  var vuln  = m.vulnSLApct  != null ? +m.vulnSLApct  : 63;
  var siem  = m.siemDays    != null ? +m.siemDays    : 14;
  var mttd  = m.mttdHrs     != null ? +m.mttdHrs     : 24;
  var mttr  = m.mttrHrs     != null ? +m.mttrHrs     : 8;

  var base  = ctrl.score || 70;
  var label = (ctrl.name || ctrl.ref || "").toLowerCase();

  // Identify the most relevant metric for this control
  var rel;
  if (/access.control|mfa|multi.factor|authenticat|privileged|identity|account.manag/i.test(label))
    rel = mfa * 0.55 + pam * 0.45;
  else if (/audit|log|retention|siem|event.log/i.test(label))
    rel = Math.min(100, siem / 90 * 100);
  else if (/training|awareness|workforce|personnel|clearance|security.culture/i.test(label))
    rel = train;
  else if (/patch|vulnerab|cve|config|hardening|update/i.test(label))
    rel = patch * 0.55 + vuln * 0.45;
  else if (/incident.response|playbook|mttr|recovery.time|containment/i.test(label))
    rel = Math.max(0, Math.min(100, 100 - (mttr - 4) / 4 * 15));
  else if (/detect|monitor|soc|mttd|anomal|alert/i.test(label))
    rel = Math.max(0, Math.min(100, 100 - (mttd - 8) / 8 * 15));
  else if (/edr|endpoint.security|malware|antivirus|crowdstrike|defender/i.test(label))
    rel = edr;
  else
    rel = mfa*0.22 + edr*0.18 + patch*0.20 + train*0.16 + pam*0.12 + vuln*0.12;

  // Finding severity penalty (open gap = score reduction)
  var pen = 0;
  if (ctrl.finding) {
    var f = FINDINGS.find(function(x){ return x.id === ctrl.finding; });
    if (f) pen = f.sev==="Critical"?20 : f.sev==="High"?12 : f.sev==="Medium"?6 : 0;
  }

  // Calibration: adjustment from metrics relative to 70-point baseline
  // rel=70 → adj=0 (unchanged from static). rel=90 → +6. rel=50 → -6.
  var metricsAdj = Math.round((rel - 70) * 0.30);

  return Math.max(25, Math.min(96, base + metricsAdj - pen));
}

// Compute a compliance section score as the weighted average of its controls
function computeSectionScore(section, metrics) {
  var ctrls = section.controls || [];
  if (ctrls.length === 0) return section.score || 70;
  var total = ctrls.reduce(function(s, c){ return s + computeComplianceScore(c, metrics); }, 0);
  return Math.max(25, Math.min(96, Math.round(total / ctrls.length)));
}



// AUDITABLE: Process exposure is now calculated dynamically based on:
// - Organization size (revenue, members, PHI records)
// - Process score (lower score = higher exposure)
// - Finding severity counts
function calculateProcessExposure(proc, orgSize, metrics) {
  orgSize = orgSize || {};
  var revenue = orgSize.revenue || 1750000000; // $1.75B default
  var members = orgSize.members || 3000000;   // 3M default
  var phiRecs = orgSize.phiRecords || 3000000; // 3M default

  // Base exposure factor from organization size (larger org = larger exposure)
  var sizeFactor = (revenue / 1000000000) * 0.4 + // 40% from revenue
                   (members / 1000000) * 0.3 +      // 30% from members
                   (phiRecs / 1000000) * 0.3;        // 30% from PHI records

  // Process score impact (score 100 = 0% penalty, score 0 = 100% penalty)
  var score = proc.score || 70;
  var scorePenalty = Math.max(0, (100 - score) / 100);

  // Finding severity multiplier
  var crits = proc.crits || 0;
  var highs = proc.highs || 0;
  var findingMult = 1 + (crits * 0.15) + (highs * 0.05); // Each critical = +15%, each high = +5%

  // Calculate exposure in millions
  var baseExposure = sizeFactor * 1000; // Base $1B per unit of size factor
  var exposure = baseExposure * scorePenalty * findingMult;

  return Math.round(exposure); // Return in millions
}

// Calculate total organizational exposure
function calculateTotalExposure(procs, orgSize, metrics) {
  var total = 0;
  (procs || []).forEach(function(proc){
    total += calculateProcessExposure(proc, orgSize, metrics);
  });
  return total;
}

