// ─── Range helper ─────────────────────────────────────────────────────────────
function rangeVal(ranges, label) {
  if (!label) { return 0; }
  var found = ranges.find(function(r){ return r[0]===label; });
  return found ? found[1] : 0;
}

// ─── Org profile lookup ───────────────────────────────────────────────────────
function getOrgProfile(orgType, orgName) {
  var base = ORG_PROFILES_RICH[orgType] || ORG_PROFILES_RICH["Commercial Health Plan"];
  var nameLower = (orgName||"").toLowerCase();
  var hint = null;
  INSURER_HINTS_RICH.forEach(function(h) {
    if (!hint) {
      h.patterns.forEach(function(p){ if (nameLower.includes(p)) { hint = h; } });
    }
  });
  return { base:base, hint:hint, detectedType: hint ? hint.type : orgType };
}

// ─── Exposure calculation ─────────────────────────────────────────────────────
// ─── Additional range tables ───────────────────────────────────────────────────
var PROVIDER_RANGES   = [["Under 5,000",2500],["5,000-20,000",12500],["20,000-50,000",35000],["50,000-100,000",75000],["100,000-250,000",175000],["250,000-500,000",375000],["Over 500,000",600000]];
var DOWNTIME_RANGES   = [["1-3 days",2],["4-7 days",5],["1-2 weeks",10],["2-4 weeks",21],["1-3 months",60]];
var IT_BUDGET_RANGES  = [["Under $10M",5e6],["$10M-$25M",17e6],["$25M-$50M",37e6],["$50M-$100M",75e6],["$100M-$250M",175e6],["$250M-$500M",375e6],["Over $500M",600e6]];
var CHURN_RANGES      = [["1-2%",0.015],["3-5%",0.04],["6-10%",0.08],["11-20%",0.155],["Over 20%",0.25]];
var RANSOM_RANGES     = [["No coverage",0],["Under $1M",0.5e6],["$1M-$5M",3e6],["$5M-$10M",7.5e6],["$10M-$25M",17.5e6],["Over $25M",30e6]];
var PREMIUM_RANGES    = [["Under $100/mo",75],["$100-$300/mo",200],["$300-$600/mo",450],["$600-$1,200/mo",900],["Over $1,200/mo",1500]];

// ─── Expanded calcExposure v2 ─────────────────────────────────────────────────
function calcExposure(orgType, orgName, mem, rev, claimsNum, cmsNum, statesNum, insNum,
                      providerCount, downtimeDays, memberPremium, churnRate,
                      ransomCoverage, itBudget, isPublic) {
  var profile  = getOrgProfile(orgType, orgName);
  var p        = profile.base;
  var methods  = p ? (p.expMethods||[]) : [];
  var rows     = [];

  // ── 1. PHI Breach ($164/record — IBM 2024) ──────────────────────
  if (mem > 0) {
    var phiTotal = Math.round(mem * 164 / 1e6);
    rows.push({
      cat:"Breach Response",
      label:"PHI Breach Cost",
      exp:phiTotal,
      formula:fmtNum(mem)+" members \xd7 $164/record (IBM Cost of Breach 2024)"
    });
  }

  // ── 2. Notification + Credit Monitoring ─────────────────────────
  if (mem > 0) {
    var notifCost = Math.round(mem * 35 / 1e6);  // $15 notification + $20 credit monitoring
    rows.push({
      cat:"Breach Response",
      label:"Notification & Credit Monitoring",
      exp:notifCost,
      formula:fmtNum(mem)+" members \xd7 $35 (OCR required notification + credit monitoring)"
    });
  }

  // ── 3. Forensics & IR ───────────────────────────────────────────
  if (mem > 0 || rev > 0) {
    var forensics = mem > 1e6 ? 4 : mem > 100000 ? 2 : 1;
    rows.push({
      cat:"Breach Response",
      label:"Forensics & Incident Response",
      exp:forensics,
      formula:"Digital forensics, IR retainer activation, legal hold — industry avg $1-4M for health plans"
    });
  }

  // ── 4. Business Interruption ────────────────────────────────────
  if (rev > 0 && downtimeDays > 0) {
    var revenuePerDay = rev / 365;
    var biLoss = Math.round(revenuePerDay * downtimeDays / 1e6);
    rows.push({
      cat:"Business Interruption",
      label:"Revenue Loss / Downtime",
      exp:biLoss,
      formula:"$"+Math.round(revenuePerDay/1e6)+"M/day \xd7 "+downtimeDays+" estimated downtime days ("+fmtD(rev)+" \xf7 365)"
    });
  }

  // ── 5. Claims / Operations Disruption ───────────────────────────
  if (claimsNum > 0 && downtimeDays > 0) {
    var claimsPerDay = claimsNum / 250;
    var claimsDisruption = Math.round(claimsPerDay * downtimeDays * 0.05 / 1e6); // 5% penalty/interest
    if (claimsDisruption > 0) {
      rows.push({
        cat:"Business Interruption",
        label:"Claims Processing Disruption",
        exp:claimsDisruption,
        formula:"Delayed claims penalties + interest at 5% on "+fmtNum(Math.round(claimsPerDay))+" claims/day \xd7 "+downtimeDays+" days"
      });
    }
  }

  // ── 6. Member Churn / Revenue Loss ──────────────────────────────
  if (mem > 0 && churnRate > 0 && memberPremium > 0) {
    var churnedMembers = Math.round(mem * churnRate);
    var annualPremiumLoss = Math.round(churnedMembers * memberPremium * 12 / 1e6);
    rows.push({
      cat:"Reputational",
      label:"Member Churn & Premium Loss",
      exp:annualPremiumLoss,
      formula:fmtNum(churnedMembers)+" churned members (\xd7 "+Math.round(churnRate*100)+"%) \xd7 $"+memberPremium+"/mo \xd7 12 months"
    });
  }

  // ── 7. OCR / HIPAA Fines ────────────────────────────────────────
  if (mem > 0) {
    var ocrFine = mem > 5e6 ? 4.5 : mem > 1e6 ? 2.5 : mem > 100000 ? 1.5 : 0.5;
    rows.push({
      cat:"Regulatory",
      label:"HIPAA OCR Penalty",
      exp:Math.round(ocrFine),
      formula:"Willful neglect tier: $"+ocrFine+"M (max $1.9M/violation category/year — OCR 2024 caps)"
    });
  }

  // ── 8. CMS Sanctions ────────────────────────────────────────────
  if (cmsNum > 0 && methods.includes("cms_sanctions")) {
    var cmsFine = Math.round(cmsNum * 0.10 / 1e6);
    rows.push({
      cat:"Regulatory",
      label:"CMS Contract Sanctions",
      exp:cmsFine,
      formula:"Up to 10% of $"+(cmsNum/1e9).toFixed(1)+"B CMS contract (42 CFR \xa7422.752 / \xa7438.730 — suspension or termination)"
    });
  }

  // ── 9. RADV Risk ───────────────────────────────────────────────
  if (cmsNum > 0 && methods.includes("radv_recovery")) {
    var radvExp = Math.round(cmsNum * 0.02 / 1e6);
    rows.push({
      cat:"Regulatory",
      label:"CMS RADV Premium Recovery",
      exp:radvExp,
      formula:"Avg 2% risk-adjustment repayment on $"+(cmsNum/1e9).toFixed(1)+"B CMS contract (RADV audit methodology)"
    });
  }

  // ── 11. FWA / Claims Fraud ──────────────────────────────────────
  if (claimsNum > 0 && methods.includes("fwa")) {
    var fwaExp = Math.round(claimsNum * 0.03 / 1e6);
    rows.push({
      cat:"Fraud & Abuse",
      label:"Claims Fraud & Abuse Exposure",
      exp:fwaExp,
      formula:"3% FWA rate on $"+(claimsNum/1e9).toFixed(1)+"B annual claims (CMS National Health Expenditure benchmark)"
    });
  }

  // ── 12. Provider Liability ──────────────────────────────────────
  if (providerCount > 0 && mem > 0) {
    var providerExp = Math.round(providerCount * 500 / 1e6);
    if (providerExp > 0) {
      rows.push({
        cat:"Third-Party Liability",
        label:"Provider Network Data Liability",
        exp:providerExp,
        formula:fmtNum(providerCount)+" in-network providers \xd7 $500 avg provider record value (credentialing data, SSN, DEA)"
      });
    }
  }

  // ── 13. Class Action Settlement ─────────────────────────────────
  if (mem > 0) {
    var classFactor = mem > 5e6 ? 50 : mem > 1e6 ? 20 : mem > 100000 ? 8 : 2;
    rows.push({
      cat:"Legal",
      label:"Class Action Settlement",
      exp:classFactor,
      formula:"Estimate based on member count tier — comparable settlements (Anthem $115M, Banner Health $6M, Premera $74M)"
    });
  }

  // ── 14. Legal Fees ──────────────────────────────────────────────
  if (mem > 0) {
    var legalFees = mem > 1e6 ? 8 : mem > 100000 ? 4 : 2;
    rows.push({
      cat:"Legal",
      label:"Legal Defense & Outside Counsel",
      exp:legalFees,
      formula:"Breach litigation, regulatory defense, attorney-client privilege review — avg $2-8M for health plans"
    });
  }

  // ── 15. SEC Disclosure Cost (public only) ───────────────────────
  if (isPublic && rev > 0) {
    var secCost = Math.round(rev * 0.005 / 1e6);
    rows.push({
      cat:"Capital Markets",
      label:"SEC Materiality & Disclosure",
      exp:secCost,
      formula:"0.5% of $"+(rev/1e9).toFixed(1)+"B revenue — SEC 4-day disclosure triggers trading halt risk, restatement cost, and investor litigation"
    });
  }

  // ── 16. Cyber Ransom ────────────────────────────────────────────
  if (rev > 0) {
    var ransomEstimate = rev > 10e9 ? 50 : rev > 1e9 ? 20 : rev > 100e6 ? 5 : 2;
    rows.push({
      cat:"Extortion",
      label:"Ransomware / Extortion Demand",
      exp:ransomEstimate,
      formula:"Industry avg: 0.2-0.5% of revenue — Scripps Health $21M, Change Healthcare $22M ransom paid (Feb 2024)"
    });
  }

  // ── 17. IT Recovery & Rebuild ───────────────────────────────────
  if (itBudget > 0) {
    var itRecovery = Math.round(itBudget * 0.15 / 1e6);
    rows.push({
      cat:"Recovery",
      label:"IT Recovery & Infrastructure Rebuild",
      exp:itRecovery,
      formula:"15% of $"+Math.round(itBudget/1e6)+"M IT budget — emergency hardware, cloud migration, security tooling refresh"
    });
  }

  // Group by category
  var cats = {};
  rows.forEach(function(r){
    if(!cats[r.cat]){cats[r.cat]=[];}
    cats[r.cat].push(r);
  });

  var total = rows.reduce(function(a,r){return a+r.exp;},0);
  var ins   = insNum > 0 ? Math.round(insNum/1e6) : 0;
  var net   = ins > 0 ? Math.max(0, total - ins) : total;
  var ransCoverage = ransomCoverage > 0 ? Math.round(ransomCoverage/1e6) : 0;

  return {rows:rows, cats:cats, total:total, net:net, ins:ins, ransomCoverage:ransCoverage};
}

