// Get all vendor IDs pre-selected for an org type
function getVendorPreset(orgType) {
  var preset = VENDOR_PRESETS[orgType];
  if (!preset) { return {}; }
  var sel = {};
  ["core","pbm","um","provider","member","finance","govt","analytics","mailing"].forEach(function(cat) {
    if (preset[cat]) {
      preset[cat].forEach(function(id) { sel[id] = true; });
    }
  });
  return sel;
}

// Human-readable summary of what was pre-selected and why (for Briana narration)
function getVendorPresetNarration(orgType, orgName) {
  var name = orgName || "your organization";
  var preset = VENDOR_PRESETS[orgType];
  if (!preset) {
    return "Here's your vendor ecosystem. Select every third-party vendor that touches your data or operations. I've left this blank since I don't have enough context about your organization type yet. Start with your clearinghouse, then your pharmacy benefit manager, then utilization management.";
  }
  var coreCount   = (preset.core   ||[]).length;
  var pbmCount    = (preset.pbm    ||[]).length;
  var umCount     = (preset.um     ||[]).length;
  var govtCount   = (preset.govt   ||[]).length;
  var totalCount  = Object.keys(getVendorPreset(orgType)).length;
  var lines = [
    "Here's your vendor ecosystem. Based on what you told me about "+name
    +" being a "+orgType+", I've pre-selected "+totalCount+" vendors that organizations like yours typically work with.",
  ];
  if (coreCount)  lines.push("The "+coreCount+" core vendors cover your claims clearinghouse and adjudication platform — these touch every transaction.");
  if (pbmCount)   lines.push("I've included "+pbmCount+" pharmacy benefit manager"+( pbmCount>1?"s":"")+", since PBM data sharing is one of the highest PHI-volume relationships you have.");
  if (umCount)    lines.push("Utilization management vendors like Cotiviti and eviCore are pre-selected because prior authorization and clinical review data flows carry significant compliance risk.");
  if (govtCount)  lines.push("I've included CMS and government-side vendors since "+orgType+"s have direct regulatory data exchange obligations.");
  lines.push("Take a look and deselect anything that doesn't apply. Each vendor that handles member data is a potential path for a breach, so accuracy here drives your compliance and exposure calculations.");
  return lines.join(" ");
}


