// Returns the first connected ITSM system, or null if none selected
function getActiveITSM(infraSel) {
  var sel = infraSel || _globalInfraSel || {};
  var order = ["snow","jira","remedy","freshservice","cherwell"];
  for (var _i=0; _i<order.length; _i++) {
    var _s = ITSM_SYSTEMS[order[_i]];
    if (_s.toolKeys.some(function(k){ return !!sel[k]; })) { return _s; }
  }
  return null;
}

// Returns all connected ITSM systems in priority order
function getConnectedITSMs(infraSel) {
  var sel = infraSel || _globalInfraSel || {};
  return ["snow","jira","remedy","freshservice","cherwell"]
    .map(function(id){ return ITSM_SYSTEMS[id]; })
    .filter(function(sys){ return sys.toolKeys.some(function(k){ return !!sel[k]; }); });
}

// Build ROUTES array from ITSM_SYSTEMS + SOAR + Manual, with live connected status
function buildRoutes(infraSel) {
  var sel = infraSel || {};
  var routes = ["snow","jira","remedy","freshservice","cherwell"].map(function(id) {
    var sys = ITSM_SYSTEMS[id];
    return {
      id:sys.id, label:sys.shortLabel, color:sys.color, icon:sys.icon,
      toolKeys:sys.toolKeys, desc:sys.desc, states:sys.states,
      ticketType:sys.ticketType,
      connected:sys.toolKeys.some(function(k){ return !!sel[k]; }),
    };
  });
  routes.push({
    id:"soar", label:"SOAR", color:"#A78BFA", icon:"⚙",
    toolKeys:["SIEM:Splunk SIEM","SIEM:Microsoft Sentinel","SIEM:IBM QRadar","SIEM:Sumo Logic"],
    desc:"Triggers a security playbook in Splunk SOAR, XSOAR, Tines, or Swimlane with full finding context.",
    states:["Triggered","Running","Pending Approval","Complete"], ticketType:"Playbook",
    connected:["SIEM:Splunk SIEM","SIEM:Microsoft Sentinel","SIEM:IBM QRadar","SIEM:Sumo Logic"]
      .some(function(k){ return !!sel[k]; }),
  });
  routes.push({
    id:"manual", label:"Manual", color:"#0FBB80", icon:"📄",
    toolKeys:[], desc:"Generate a remediation package PDF for offline or manual execution.",
    states:["Downloaded","In Progress","Complete"], ticketType:"Package", connected:true,
  });
  return routes;
}
var ROUTES = buildRoutes(_globalInfraSel);





