// ─── MetricDetailModal — universal click-through for all dashboard stats ───────
function mk(k,v){var _o={};_o[k]=v;return _o;}

function isDemoOrg(orgName) {
  if (!orgName) { return true; }
  var lo = orgName.toLowerCase();
  if (lo.includes("meridian") || lo.includes("demo") || orgName === DEMO_ORG_NAME) { return true; }
  var matched = false;
  INSURER_HINTS_RICH.forEach(function(h) {
    h.patterns.forEach(function(p){ if (lo.includes(p)) { matched = true; } });
  });
  return matched;
}

