function Spark(props) {
  var data, clr; data=props.data; clr=props.clr;
  var w = 80; var h = 26;
  if (!data || data.length < 2) { return <span/>; }
  var lo  = Math.min.apply(null, data);
  var hi  = Math.max.apply(null, data);
  var rng = hi - lo || 1;
  var d   = data.map(function(v, i) {
    return (i===0?"M":"L") + ((i/(data.length-1))*w).toFixed(1) + "," +
      (h-3-((v-lo)/rng)*(h-6)).toFixed(1);
  }).join(" ");
  var color = clr || hc(data[data.length-1]);
  return (
    <svg width={w} height={h} style={{display:"block"}}>
      <path d={d} fill="none" stroke={color} strokeWidth={1.5} strokeLinejoin="round"/>
    </svg>
  );
}

