var CYBERRX_API = (typeof window!=='undefined'&&window.__CYBERRX_API)||import.meta.env.VITE_API_URL||'http://localhost:3001';

// ── Org Profile Persistence Helpers ────────────────────────────────────────────────

/**
 * Save org profile to backend API
 * @param {Object} orgData - Complete org profile data from SetupBot
 * @returns {Promise<Object>} - Response with orgId and status
 */
function saveOrgProfile(orgData) {
  if (!orgData || !orgData.orgName) {
    return Promise.reject(new Error('Invalid org data: missing orgName'));
  }

  // Generate org ID from org name
  var orgId = orgData.orgName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, 50);

  return fetch(CYBERRX_API + '/api/orgs/' + orgId, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(orgData)
  })
  .then(function(res) {
    if (!res.ok) {
      if (res.status === 404) {
        throw new Error('Organization not found');
      } else if (res.status === 400) {
        return res.json().then(function(err) {
          throw new Error(err.error || 'Invalid data');
        });
      } else {
        throw new Error('Failed to save profile (HTTP ' + res.status + ')');
      }
    }
    return res.json();
  })
  .then(function(data) {
    // Save org ID to localStorage
    try {
      localStorage.setItem('cyberrx_org_id', orgId);
    } catch(e) {
      console.warn('Failed to save org ID to localStorage:', e.message);
    }
    return { orgId: orgId, data: data };
  });
}

/**
 * Load org profile from backend API
 * @param {string} orgId - Organization ID
 * @returns {Promise<Object>} - Org profile data
 */
function loadOrgProfile(orgId) {
  if (!orgId) {
    return Promise.reject(new Error('orgId is required'));
  }

  return fetch(CYBERRX_API + '/api/orgs/' + orgId, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + localStorage.getItem('authToken')
    }
  })
  .then(function(res) {
    if (!res.ok) {
      if (res.status === 404) {
        throw new Error('Organization not found');
      }
      throw new Error('Failed to load profile (HTTP ' + res.status + ')');
    }
    return res.json();
  })
  .then(function(data) {
    return data.setup_json || {};
  });
}

/**
 * Check if org exists in backend
 * @param {string} orgId - Organization ID
 * @returns {Promise<boolean>} - True if org exists
 */
function orgExists(orgId) {
  if (!orgId) {
    return Promise.resolve(false);
  }

  return fetch(CYBERRX_API + '/api/orgs/' + orgId + '/exists', {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + localStorage.getItem('authToken')
    }
  })
  .then(function(res) {
    if (!res.ok) {
      return false;
    }
    return res.json();
  })
  .then(function(data) {
    return data.exists || false;
  })
  .catch(function() {
    return false;
  });
}

// ── localStorage Backup Functions ─────────────────────────────────────────────────

/**
 * Save org data to localStorage as backup
 * @param {Object} orgData - Complete org profile data
 */
function saveOrgToLocalStorage(orgData) {
  try {
    localStorage.setItem('cyberrx_org_backup', JSON.stringify(orgData));
    if (orgData && orgData.orgName) {
      var orgId = orgData.orgName
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '')
        .substring(0, 50);
      localStorage.setItem('cyberrx_org_id', orgId);
    }
    return true;
  } catch(e) {
    console.warn('Failed to save org backup to localStorage:', e.message);
    return false;
  }
}

/**
 * Load org data from localStorage backup
 * @returns {Object|null} - Org data or null if not found
 */
function loadOrgFromLocalStorage() {
  try {
    var backup = localStorage.getItem('cyberrx_org_backup');
    if (backup) {
      return JSON.parse(backup);
    }
    return null;
  } catch(e) {
    console.warn('Failed to load org backup from localStorage:', e.message);
    return null;
  }
}

/**
 * Get saved org ID from localStorage
 * @returns {string|null} - Org ID or null
 */
function getSavedOrgId() {
  try {
    return localStorage.getItem('cyberrx_org_id');
  } catch(e) {
    return null;
  }
}

/**
 * Clear org backup from localStorage
 */
function clearOrgBackup() {
  try {
    localStorage.removeItem('cyberrx_org_backup');
    localStorage.removeItem('cyberrx_org_id');
  } catch(e) {
    console.warn('Failed to clear org backup:', e.message);
  }
}

// ── Validation & Sanitization ─────────────────────────────────────────────────────

/**
 * Validate org data before saving
 * @param {Object} data - Org data to validate
 * @returns {Object} - { valid: boolean, errors: Array }
 */
function validateOrgDataBeforeSave(data) {
  var errors = [];

  if (!data) {
    return { valid: false, errors: ['No data provided'] };
  }

  // Required fields
  if (!data.orgName || !data.orgName.trim()) {
    errors.push('Organization name is required');
  }

  if (!data.orgType || !data.orgType.trim()) {
    errors.push('Organization type is required');
  }

  return {
    valid: errors.length === 0,
    errors: errors
  };
}

/**
 * Sanitize user input to prevent XSS
 * @param {string} input - Input to sanitize
 * @returns {string} - Sanitized input
 */
function sanitizeInput(input) {
  if (typeof input !== 'string') {
    return input;
  }
  return input
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
}

// ── Shared TTS helper - reads voice settings and speaks using appropriate provider ─────
// Global tracker for currently playing audio elements
window._cx_active_audios = window._cx_active_audios || [];

function speakWithSavedVoice(text) {
  // Cancel any ongoing speech and audio
  if (window.speechSynthesis) { window.speechSynthesis.cancel(); }

  // Stop all previously playing audio elements
  if (window._cx_active_audios && window._cx_active_audios.length > 0) {
    window._cx_active_audios.forEach(function(audio){
      try {
        audio.pause();
        audio.currentTime = 0;
      } catch(e) {}
    });
    window._cx_active_audios = [];
  }

  // Read voice settings from localStorage
  var LS = window.localStorage || { getItem:function(){return null;} };
  var provider = LS.getItem("cx_voice_provider") || "browser";
  var elKey    = LS.getItem("cx_el_key") || "";
  var oaiKey   = LS.getItem("cx_tts_key") || "";
  var model    = LS.getItem("cx_voice_model") || "nova";

  // ── ElevenLabs TTS ────────────────────────────────────────────────────────
  if (provider === "elevenlabs" && elKey) {
    var EL_IDS = {
      "Rachel":"21m00Tcm4TlvDq8ikWAM","Bella":"EXAVITQu4vr4xnSDxMaL",
      "Elli":"MF3mGyEYCl7XYWbV9V6O","Antoni":"ErXwobaYiN019PkySvjV",
      "Josh":"TxGEqnHWrfWFTfGW9XjX","Adam":"pNInz6obpgDQGcFmaJgB",
      "Sam":"yoZ06aMxZJJ28mfd3POQ","Domi":"AZnzlk1XvdvUeBnXmlld",
      "Charlotte":"XB0fDUnXU5powFXDhCwa","Callum":"N2lVS1w4EtoT3dr4eOWO"
    };
    var vid = EL_IDS[model] || EL_IDS["Rachel"];
    fetch("https://api.elevenlabs.io/v1/text-to-speech/"+vid, {
      method:"POST",
      headers:{"xi-api-key":elKey,"Content-Type":"application/json","Accept":"audio/mpeg"},
      body:JSON.stringify({
        text:text,
        model_id:"eleven_turbo_v2_5",
        voice_settings:{stability:0.45,similarity_boost:0.78,style:0.08,use_speaker_boost:true}
      })
    }).then(function(res){
      if(!res.ok)throw new Error("ElevenLabs "+res.status);
      return res.blob();
    }).then(function(blob){
      var url=URL.createObjectURL(blob);
      var audio=new Audio(url);
      audio.onended=function(){
        URL.revokeObjectURL(url);
        // Remove from active audios
        var idx = window._cx_active_audios.indexOf(audio);
        if (idx > -1) { window._cx_active_audios.splice(idx, 1); }
      };
      audio.onerror=function(){
        URL.revokeObjectURL(url);
        var idx = window._cx_active_audios.indexOf(audio);
        if (idx > -1) { window._cx_active_audios.splice(idx, 1); }
      };
      // Register audio before playing
      window._cx_active_audios.push(audio);
      audio.play().catch(function(e){
        console.warn("ElevenLabs audio blocked:",e);
        URL.revokeObjectURL(url);
        var idx = window._cx_active_audios.indexOf(audio);
        if (idx > -1) { window._cx_active_audios.splice(idx, 1); }
      });
    }).catch(function(err){
      console.warn("ElevenLabs failed, falling back to browser:",err.message);
      // Continue to browser TTS below
    });
    return;
  }

  // ── OpenAI TTS ───────────────────────────────────────────────────────────
  if (provider === "openai" && oaiKey && oaiKey.startsWith("sk-")) {
    fetch("https://api.openai.com/v1/audio/speech", {
      method:"POST",
      headers:{"Authorization":"Bearer "+oaiKey,"Content-Type":"application/json"},
      body:JSON.stringify({
        model:"tts-1-hd",
        input:text,
        voice:model
      })
    }).then(function(res){
      if(!res.ok)throw new Error("OpenAI "+res.status);
      return res.blob();
    }).then(function(blob){
      var url=URL.createObjectURL(blob);
      var audio=new Audio(url);
      audio.onended=function(){
        URL.revokeObjectURL(url);
        // Remove from active audios
        var idx = window._cx_active_audios.indexOf(audio);
        if (idx > -1) { window._cx_active_audios.splice(idx, 1); }
      };
      audio.onerror=function(){
        URL.revokeObjectURL(url);
        var idx = window._cx_active_audios.indexOf(audio);
        if (idx > -1) { window._cx_active_audios.splice(idx, 1); }
      };
      // Register audio before playing
      window._cx_active_audios.push(audio);
      audio.play().catch(function(e){
        console.warn("OpenAI audio blocked:",e);
        URL.revokeObjectURL(url);
        var idx = window._cx_active_audios.indexOf(audio);
        if (idx > -1) { window._cx_active_audios.splice(idx, 1); }
      });
    }).catch(function(err){
      console.warn("OpenAI failed, falling back to browser:",err.message);
      // Continue to browser TTS below
    });
    return;
  }

  // ── Browser TTS (fallback or default) ─────────────────────────────────────
  if (!window.speechSynthesis) { return; }

  var u = new window.SpeechSynthesisUtterance(text);
  u.rate = 0.92;
  u.pitch = 1.0;
  u.volume = 1.0;

  var vv = window.speechSynthesis.getVoices();
  var savedVoiceName = LS.getItem("cx_browser_voice") || "";

  // Try to use saved voice
  var pref = null;
  if (savedVoiceName) {
    pref = vv.find(function(v){ return (v.name||'') === savedVoiceName; });
  }

  // Fallback to good quality voices
  if (!pref) {
    pref = vv.find(function(v){
      var n=v.name||'';
      return n==='Microsoft Aria Online (Natural) - English (United States)'||
             n==='Microsoft Jenny Online (Natural) - English (United States)';
    })||vv.find(function(v){
      return (v.name||'').indexOf('Natural')>=0&&(v.lang||'').indexOf('en')===0;
    })||vv.find(function(v){return(v.name||'')==='Samantha';})
      ||vv.find(function(v){return(v.name||'')==='Google US English';});
  }

  if (pref) { u.voice = pref; }
  window.speechSynthesis.speak(u);
}

