  function parseCMDB() {
    var input = cmdbText.trim();
    if (!input) { setAiError("Please provide application data first."); return; }
    setAiParsing(true); setAiError(""); setAiResult(null); setParsePct(0); setParseStep(0);
    var stepIdx = 0;
    var progressIv = setInterval(function() {
      stepIdx++;
      setParsePct(Math.min(88, Math.round((stepIdx/PARSE_STEPS.length)*88)));
      setParseStep(stepIdx);
      if (stepIdx >= PARSE_STEPS.length-1) { clearInterval(progressIv); }
    }, 700);
    var procList = PROCS.map(function(p){ return p.id+":"+p.name; }).join(", ");
    var orgCtx   = orgType ? "Organization type: "+orgType+"." : "";
    var prompt = [
      "You are a healthcare IT asset classification expert. Analyze this application inventory.",
      orgCtx,
      "Map each application to ONE of these healthcare payer business processes: "+procList,
      "For each application: name, process (one of: claims/enroll/provider/care/finance/member_svc/compliance/it_sec), type (Core Admin System/Integration/Security Tool/Analytics/Infrastructure/Vendor Portal/Custom Application), vendor, connection (REST API/SFTP/Agent/Database Connector/EDI/Log Forwarding/Manual Upload), notes",
      "Return ONLY valid JSON: {source,summary,apps:[{name,process,type,vendor,connection,notes}]}",
      "DATA:", input.slice(0,6000),
    ].join("\n");
    fetch("https://api.anthropic.com/v1/messages", {
      method:"POST", headers:{"Content-Type":"application/json"},
      body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:2000,messages:[{role:"user",content:prompt}]})
    })
    .then(function(r){ return r.json(); })
    .then(function(raw) {
      clearInterval(progressIv); setParsePct(95); setParseStep(PARSE_STEPS.length);
      var txt = (raw.content||[]).filter(function(b){return b.type==="text";}).map(function(b){return b.text;}).join("");
      var clean = txt.replace(new RegExp("```json","g"),"").replace(new RegExp("```","g"),"").trim();
      var parsed = JSON.parse(clean);
      var newSel = {}; var newConn = {};
      (parsed.apps||[]).forEach(function(a) {
        if (!newSel[a.process]) { newSel[a.process] = {}; }
        newSel[a.process][a.name] = true;
        if (a.connection) { newConn[a.process+"__"+a.name] = a.connection; }
      });
      setAppSel(function(s){ return Object.assign({},s,newSel); });
      setAppConn(function(c){ return Object.assign({},c,newConn); });
      setTimeout(function() {
        setParsePct(100);
        setTimeout(function(){ setAiResult(parsed); setAiParsing(false); }, 400);
      }, 300);
    })
    .catch(function(e) {
      clearInterval(progressIv);
      setAiError("Analysis failed: "+e.message);
      setAiParsing(false); setParsePct(0); setParseStep(0);
    });
  }

