                      if(smk.status==='error') return React.createElement('span',{style:{color:"#EF4545",fontSize:8,fontWeight:700,background:"#EF454514",borderRadius:3,padding:"1px 6px"}},'✗ Sync failed');
                      return React.createElement('span',{style:{color:"#F5A623",fontSize:8,fontWeight:600,background:"#F5A62314",borderRadius:3,padding:"1px 6px"}},'Manual');
