// ─── Application Map — F01b — standalone page ─────────────────────────────────
function AppMap(props) {
  var go=props.go;
  var _s0=useState(null);   var selProc=_s0[0];  var setSelProc=_s0[1];
  var _s1=useState(null);   var selApp=_s1[0];   var setSelApp=_s1[1];
  var _s2=useState("all");  var filterTab=_s2[0];var setFilterTab=_s2[1];

  var allProcs = Object.keys(BIZ_APP_CATALOG);

  function AppDetail() {
    if (!selApp) { return null; }
    var app = selApp;
    var proc = PROCS.find(function(p){return p.id===app.procId;});
    var procFindings = FINDINGS.filter(function(f){return f.procId===app.procId;});
    return (
      <div>
        <button onClick={function(){setSelApp(null);}}
          style={{display:"flex",gap:6,alignItems:"center",background:"transparent",
            border:"none",color:C.acc,cursor:"pointer",fontSize:12,fontWeight:700,
            marginBottom:16,padding:0}}>
          ← Back to Application Map
        </button>
        <div style={{display:"flex",gap:12,alignItems:"flex-start",marginBottom:16}}>
          <div style={{flex:1}}>
            <h2 style={{color:C.text,fontSize:18,fontWeight:800,margin:"0 0 4px"}}>{app.name}</h2>
            <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
              <span style={{color:C.muted,fontSize:11}}>{app.vendor}</span>
              <span style={{color:C.dim}}>·</span>
              <span style={{color:C.muted,fontSize:11}}>{app.type}</span>
              {proc&&(
                <span style={{color:C.acc,fontSize:10,background:C.faint,
                  borderRadius:4,padding:"1px 7px"}}>{proc.icon} {proc.name}</span>
              )}
            </div>
          </div>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"2fr 1fr",gap:14}}>
          <div>
            <Card style={{marginBottom:10}}>
              <SH label="Connection Methods Available"/>
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {(app.conn||[]).map(function(c){
                  return (
                    <span key={c} style={{color:C.acc,fontSize:11,background:C.faint,
                      borderRadius:5,padding:"4px 10px",border:"1px solid "+C.acc+"25"}}>{c}</span>
                  );
                })}
              </div>
            </Card>
            <Card>
              <SH label={"Findings in "+((proc&&proc.name)||"this process")}/>
              {procFindings.length===0 ? (
                <div style={{color:"#0FBB80",fontSize:11}}>✓ No open findings for this process</div>
              ) : procFindings.map(function(f){
                return (
                  <div key={f.id} style={{display:"flex",gap:8,alignItems:"center",
                    padding:"7px 10px",background:C.bg,borderRadius:7,marginBottom:5,
                    border:"1px solid "+SEV_C[f.sev]+"25"}}>
                    <span style={{color:SEV_C[f.sev],fontSize:8,fontWeight:800,
                      background:SEV_B[f.sev],borderRadius:3,padding:"1px 5px"}}>{f.sev}</span>
                    <span style={{color:C.text,fontSize:11,flex:1}}>{orgText(f.title||"",orgName,orgExtras)}</span>
                    {f.act&&(
                      <button onClick={function(){go("execution",{act:f.act});}}
                        style={{background:C.acc,border:"none",color:"#fff",borderRadius:4,
                          padding:"2px 8px",cursor:"pointer",fontSize:9,fontWeight:700}}>
                        Execute
                      </button>
                    )}
                  </div>
                );
              })}
            </Card>
          </div>
          <div>
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              <Btn onClick={function(){go("bizlines");}} primary>View in Business Lines →</Btn>
              <Btn onClick={function(){go("execution");}}>Route Findings →</Btn>
              <Btn onClick={function(){go("setup",{step:5});}}>Configure Connection</Btn>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (selApp) { return <AppDetail/>; }

  var procFilter = selProc || filterTab;
  return (
    <div>

        <DashNav current="appmap" go={go}/>
      <BrianaBar pageKey="appmap" orgName={props.orgName||""} brianaOn={props.brianaOn!==false} setBrianaOn={props.setBrianaOn||function(){}}/>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
        <div>
          <h2 style={{color:C.text,fontSize:18,fontWeight:800,margin:"0 0 3px"}}>Application Map · F01b</h2>
          <div style={{color:C.muted,fontSize:12}}>All business applications mapped to processes, risks, and connection methods</div>
        </div>
        <div style={{display:"flex",gap:6}}>
          <Btn onClick={function(){go("review-mappings");}} small style={{background:"#0FBB80",borderColor:"#0FBB80"}}>✓ Review Mappings</Btn>
          <Btn onClick={function(){go("process-graph");}} small style={{background:"#3B9EFF",borderColor:"#3B9EFF"}}>⊟ Process Graph</Btn>
          <Btn onClick={function(){go("bizlines");}} small>Business Lines</Btn>
          <Btn onClick={function(){go("setup",{step:5});}} small>Configure →</Btn>
        </div>
      </div>

      {/* Process filter tabs */}
      <div style={{display:"flex",gap:0,marginBottom:14,borderBottom:"1px solid "+C.border,overflowX:"auto"}}>
        <button onClick={function(){setSelProc(null);setFilterTab("all");}}
          style={{background:"transparent",border:"none",
            borderBottom:"2px solid "+(filterTab==="all"?C.acc:"transparent"),
            color:filterTab==="all"?C.acc:C.muted,padding:"8px 14px",cursor:"pointer",
            fontSize:11,fontWeight:filterTab==="all"?700:400,marginBottom:-1,whiteSpace:"nowrap"}}>
          All Applications
        </button>
        {PROCS.map(function(p){
          var isActive = selProc===p.id;
          var cat = BIZ_APP_CATALOG[p.id];
          var count = cat?(cat.sampleApps||[]).length:0;
          return (
            <button key={p.id}
              onClick={function(){setSelProc(isActive?null:p.id);setFilterTab(isActive?"all":p.id);}}
              style={{background:"transparent",border:"none",
                borderBottom:"2px solid "+(isActive?C.acc:"transparent"),
                color:isActive?C.acc:C.muted,padding:"8px 14px",cursor:"pointer",
                fontSize:11,fontWeight:isActive?700:400,marginBottom:-1,whiteSpace:"nowrap"}}>
              {p.icon} {p.name} ({count})
            </button>
          );
        })}
      </div>

      {/* App grid */}
      {(selProc ? [selProc] : allProcs).map(function(pid){
        var cat = BIZ_APP_CATALOG[pid];
        var proc = PROCS.find(function(p){return p.id===pid;});
        if (!cat||!proc) { return null; }
        var procFinds = FINDINGS.filter(function(f){return f.procId===pid;});
        var critCount = procFinds.filter(function(f){return f.sev==="Critical";}).length;
        return (
          <div key={pid} style={{marginBottom:18}}>
            {!selProc&&(
              <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:10}}>
                <span style={{fontSize:20}}>{proc.icon}</span>
                <span style={{color:C.text,fontSize:14,fontWeight:800}}>{proc.name}</span>
                {critCount>0&&(
                  <span style={{color:"#EF4545",fontSize:9,fontWeight:800,background:"#EF454514",
                    borderRadius:3,padding:"2px 7px"}}>{critCount} CRITICAL</span>
                )}
                <span style={{color:C.muted,fontSize:10,marginLeft:"auto"}}>
                  {cat.sampleApps.length} applications
                </span>
              </div>
            )}
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
              {cat.sampleApps.map(function(app){
                var appWithProc = Object.assign({},app,{procId:pid});
                return (
                  <div key={app.name}
                    onClick={function(){setSelApp(appWithProc);}}
                    style={{background:C.card,border:"1px solid "+C.border,borderRadius:9,
                      padding:"12px 14px",cursor:"pointer"}}>
                    <div style={{color:C.text,fontSize:12,fontWeight:700,marginBottom:3}}>{app.name}</div>
                    <div style={{color:C.muted,fontSize:10,marginBottom:6}}>{app.vendor} · {app.type}</div>
                    <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
                      {(app.conn||[]).slice(0,2).map(function(c){
                        return (
                          <span key={c} style={{color:C.acc,fontSize:8,background:C.faint,
                            borderRadius:3,padding:"1px 5px"}}>{c}</span>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ─── Dashboard Hub — Command Center F08 ───────────────────────────────────────
// ─── Process → Application → Framework → Risk → Control Mapping ───────────────
function VendorEcosystem(props) {
  var go=props.go;
  var orgName=props.orgName||"";
  var orgExtras=props.orgTextExtras||{};
  var _s0=useState(null);   var selTier=_s0[0];   var setSelTier=_s0[1];
  var _s1=useState(null);   var selVendor=_s1[0]; var setSelVendor=_s1[1];

  // If a vendor is selected, show its full detail
  if (selVendor) {
    var tier = VENDOR_TIERS.find(function(t){
      return t.vendors.find(function(v){return v.id===selVendor;});
    });
    var vendor = tier && tier.vendors.find(function(v){return v.id===selVendor;});
    return (
      <div>
        <button onClick={function(){setSelVendor(null);}}
          style={{display:"flex",gap:6,alignItems:"center",background:"transparent",
            border:"none",color:C.acc,cursor:"pointer",fontSize:12,fontWeight:700,
            marginBottom:16,padding:0}}>
          ← Back to Ecosystem Map
        </button>
        <div style={{display:"flex",gap:10,alignItems:"flex-start",marginBottom:16}}>
          <div style={{flex:1}}>
            <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:4,flexWrap:"wrap"}}>
              <h2 style={{color:C.text,fontSize:18,fontWeight:800,margin:0}}>{vendor.name}</h2>
              <span style={{color:tier.color,fontSize:9,fontWeight:800,background:tier.color+"14",
                borderRadius:4,padding:"2px 7px"}}>Tier {tier.tier}</span>
              <span style={{color:tier.color,fontSize:9,fontWeight:700,background:tier.color+"14",
                borderRadius:4,padding:"2px 7px"}}>{vendor.risk} Risk</span>
            </div>
            <div style={{color:C.muted,fontSize:12}}>{vendor.cat}{vendor.rto?" · RTO: "+vendor.rto:""}</div>
          </div>
        </div>

        <div style={{display:"grid",gridTemplateColumns:"2fr 1fr",gap:14,marginBottom:14}}>
          <div>
            <Card style={{marginBottom:10}}>
              <div style={{color:C.muted,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>Function</div>
              <p style={{color:C.text,fontSize:13,lineHeight:1.7,margin:0}}>{orgText(vendor.function||"",orgName,orgExtras)}</p>
            </Card>
            <Card style={{marginBottom:10}}>
              <div style={{color:C.muted,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>Data Access</div>
              <div style={{display:"inline-flex",gap:6,padding:"5px 12px",
                background:"#EF454512",border:"1px solid #EF454530",borderRadius:6}}>
                <span style={{color:"#EF4545",fontSize:12,fontWeight:700}}>{vendor.dataAccess}</span>
              </div>
            </Card>
            <Card>
              <div style={{color:"#EF454580",fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>
                Control Gaps ({(vendor.gaps||[]).length})
              </div>
              {(vendor.gaps||[]).map(function(gap,i){
                var isBreach = (gap||"").toLowerCase().includes("breach") || (gap||"").toLowerCase().includes("proven");
                return (
                  <div key={i} style={{display:"flex",gap:9,alignItems:"flex-start",
                    padding:"8px 10px",borderRadius:7,marginBottom:5,
                    background:isBreach?"#EF454510":"#EF454508",
                    border:"1px solid "+(isBreach?"#EF454540":"#EF454520")}}>
                    <span style={{color:"#EF4545",fontSize:11,flexShrink:0,marginTop:1}}>{isBreach?"\ud83d\udea8":"⚠"}</span>
                    <span style={{color:C.text,fontSize:11,lineHeight:1.5}}>{gap}</span>
                  </div>
                );
              })}
            </Card>
          </div>

          <div>
            <Card style={{marginBottom:10}}>
              <div style={{color:C.muted,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>Business Processes</div>
              {(vendor.processes||[]).map(function(pid){
                var p=PROCS.find(function(x){return x.id===pid;});
                return p ? (
                  <div key={pid} style={{display:"flex",gap:7,alignItems:"center",marginBottom:6}}>
                    <span style={{fontSize:16}}>{p.icon}</span>
                    <span style={{color:C.text,fontSize:11,fontWeight:600}}>{p.name}</span>
                    <span style={{color:hc(p.score),fontSize:10,fontFamily:"monospace",marginLeft:"auto"}}>{p.score}</span>
                  </div>
                ) : null;
              })}
            </Card>
            {vendor.findings&&vendor.findings.length>0&&(
              <Card style={{marginBottom:10}}>
                <div style={{color:C.muted,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>Linked Findings</div>
                {vendor.findings.map(function(fid){
                  var f=FINDINGS.find(function(x){return x.id===fid;});
                  return f ? (
                    <div key={fid} style={{display:"flex",gap:7,alignItems:"center",
                      padding:"6px 9px",background:C.bg,borderRadius:6,marginBottom:4,
                      border:"1px solid "+SEV_C[f.sev]+"25"}}>
                      <span style={{color:SEV_C[f.sev],fontSize:8,fontWeight:800,
                        background:SEV_B[f.sev],borderRadius:3,padding:"1px 5px"}}>{f.sev}</span>
                      <span style={{color:C.text,fontSize:10,flex:1,lineHeight:1.3}}>{orgText(f.title||"",orgName,orgExtras)}</span>
                    </div>
                  ) : null;
                })}
              </Card>
            )}
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              <Btn onClick={function(){go("execution");}} primary>Route Gaps to Execution →</Btn>
              <Btn onClick={function(){go("cro");}}>View in CRO Dashboard</Btn>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>

        <DashNav current="vendormap" go={go}/>
      <BrianaBar pageKey="vendormap" orgName={props.orgName||""} brianaOn={props.brianaOn!==false} setBrianaOn={props.setBrianaOn||function(){}}/>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
        <div>
          <h2 style={{color:C.text,fontSize:18,fontWeight:800,margin:"0 0 3px"}}>
            Vendor Ecosystem Risk Map
          </h2>
          <div style={{color:C.muted,fontSize:12}}>
            Healthcare payer ecosystem — click any vendor for control gaps and linked findings
          </div>
        </div>
        <Btn onClick={function(){go("assets");}} small>Data Flow View →</Btn>
      </div>

      {/* Data flow banner */}
      <div style={{padding:"10px 14px",background:C.faint,border:"1px solid "+C.acc+"20",
        borderRadius:9,marginBottom:14}}>
        <div style={{color:C.acc,fontSize:10,fontWeight:700,marginBottom:6}}>
          End-to-End Data Flow
        </div>
        <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
          {["Provider","Clearinghouse",orgName||"[ORG]","Vendors","Member"].map(function(n,i,arr){
            return (
              <React.Fragment key={n}>
                <span style={{color:C.text,fontSize:11,fontWeight:600,
                  background:C.card,borderRadius:5,padding:"3px 9px",
                  border:"1px solid "+C.border}}>{n}</span>
                {i<arr.length-1&&<span style={{color:C.acc,fontSize:13}}>→</span>}
              </React.Fragment>
            );
          })}
          <span style={{color:C.muted,fontSize:10,marginLeft:8}}>
            PHI + PII + Financial data flows across all nodes
          </span>
        </div>
      </div>

      {/* Tier filter */}
      <div style={{display:"flex",gap:6,marginBottom:14,flexWrap:"wrap"}}>
        <button onClick={function(){setSelTier(null);}}
          style={{background:!selTier?C.acc+"14":"transparent",
            border:"1px solid "+(!selTier?C.acc+"50":C.border),
            borderRadius:20,padding:"4px 14px",cursor:"pointer",
            fontSize:11,color:!selTier?C.acc:C.muted,fontWeight:!selTier?700:400}}>
          All Vendors ({VENDOR_TIERS.reduce(function(s,t){return s+t.vendors.length;},0)})
        </button>
        {VENDOR_TIERS.map(function(t){
          var active=selTier===t.tier;
          return (
            <button key={t.tier} onClick={function(){setSelTier(active?null:t.tier);}}
              style={{background:active?t.color+"14":"transparent",
                border:"1px solid "+(active?t.color+"50":C.border),
                borderRadius:20,padding:"4px 14px",cursor:"pointer",
                fontSize:11,color:active?t.color:C.muted,fontWeight:active?700:400}}>
              {(function(){
                var short = t.label.split(" — ")[1]||t.label;
                short = short.split(",")[0].split("&")[0].trim();
                return short.length > 20 ? short.slice(0,18)+"…" : short;
              })()} ({t.vendors.length})
            </button>
          );
        })}
      </div>

      {/* Tier sections */}
      {(function(){
        var _vs = props.rootVendorSel||{};
        var _vsActive = Object.keys(_vs).length > 0;
        return VENDOR_TIERS
          .filter(function(t){return !selTier||selTier===t.tier;})
          .map(function(tierGroup){
            // If vendor selections were made in Setup, show only selected vendors in this tier
            var filteredVendors = _vsActive
              ? tierGroup.vendors.filter(function(v){return !!_vs[v.id];})
              : tierGroup.vendors;
            if (_vsActive && filteredVendors.length === 0) return null;
            return Object.assign({},tierGroup,{vendors:filteredVendors});
          })
          .filter(Boolean);
      })().map(function(tierGroup){
        return (
          <div key={tierGroup.tier} style={{marginBottom:18}}>
            <div style={{display:"flex",gap:10,alignItems:"center",marginBottom:8}}>
              <div style={{width:12,height:12,borderRadius:"50%",background:tierGroup.color}}/>
              <span style={{color:C.text,fontSize:13,fontWeight:800}}>{tierGroup.label}</span>
            </div>
            <div style={{color:C.muted,fontSize:11,marginBottom:10,paddingLeft:22}}>
              {tierGroup.desc}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
              {tierGroup.vendors.map(function(vendor){
                var gapCount = (vendor.gaps||[]).length;
                var findingCount = (vendor.findings||[]).length;
                var hasBreach = (vendor.gaps||[]).some(function(g){
                  return (g||"").toLowerCase().includes("breach")||(g||"").toLowerCase().includes("proven");
                });
                return (
                  <div key={vendor.id}
                    onClick={function(){setSelVendor(vendor.id);}}
                    style={{background:C.card,border:"1.5px solid "+(hasBreach?"#EF454540":tierGroup.color+"25"),
                      borderRadius:10,padding:"12px 14px",cursor:"pointer",
                      boxShadow:hasBreach?"0 0 0 2px #EF454520":"none"}}>
                    <div style={{display:"flex",gap:8,alignItems:"flex-start",marginBottom:6}}>
                      <div style={{flex:1}}>
                        <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
                          <span style={{color:C.text,fontSize:12,fontWeight:700}}>{vendor.name}</span>
                          {hasBreach&&(
                            <span style={{color:"#EF4545",fontSize:8,fontWeight:800,
                              background:"#EF454514",borderRadius:3,padding:"1px 5px"}}>
                              BREACH RISK
                            </span>
                          )}
                        </div>
                        <div style={{color:C.muted,fontSize:10,marginTop:1}}>{vendor.cat}</div>
                      </div>
                      <div style={{textAlign:"right",flexShrink:0}}>
                        <div style={{color:vendor.risk==="Critical"?"#EF4545":vendor.risk==="High"?"#F5A623":"#3B9EFF",
                          fontSize:9,fontWeight:800}}>{vendor.risk}</div>
                        <div style={{color:C.muted,fontSize:9}}>{vendor.rto}</div>
                      </div>
                    </div>
                    <div style={{color:C.muted,fontSize:10,lineHeight:1.4,marginBottom:8,
                      overflow:"hidden",textOverflow:"ellipsis",
                      display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical"}}>
                      {orgText(vendor.function||"",orgName,orgExtras)}
                    </div>
                    <div style={{display:"flex",gap:8,alignItems:"center"}}>
                      <span style={{color:"#EF4545",fontSize:9,background:"#EF454510",
                        borderRadius:3,padding:"1px 6px"}}>
                        {vendor.dataAccess}
                      </span>
                      <div style={{marginLeft:"auto",display:"flex",gap:4}}>
                        {gapCount>0&&(
                          <span style={{color:"#F5A623",fontSize:9,fontWeight:700,
                            background:"#F5A62314",borderRadius:3,padding:"1px 6px"}}>
                            {gapCount} gaps
                          </span>
                        )}
                        {findingCount>0&&(
                          <span style={{color:"#EF4545",fontSize:9,fontWeight:700,
                            background:"#EF454514",borderRadius:3,padding:"1px 6px"}}>
                            {findingCount} findings
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ─── Claim Lifecycle View — wired into Assets page ────────────────────────────
function ClaimLifecycle(props) {
  var go=props.go;
  var _s0=useState(null); var selStep=_s0[0]; var setSelStep=_s0[1];

  return (
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
        <div>
          <h2 style={{color:C.text,fontSize:18,fontWeight:800,margin:"0 0 3px"}}>
            End-to-End Claim Lifecycle
          </h2>
          <div style={{color:C.muted,fontSize:12}}>
            How a healthcare claim flows from member visit to payment — click any step for detail
          </div>
        </div>
        <Btn onClick={function(){go("vendormap");}} small>Vendor Ecosystem →</Btn>
      </div>

      {/* Linear flow */}
      <div style={{overflowX:"auto",marginBottom:14}}>
        <div style={{display:"flex",alignItems:"flex-start",gap:0,minWidth:900,padding:"8px 0 16px"}}>
          {CLAIM_LIFECYCLE.map(function(step,i){
            var isSelected = selStep===step.step;
            return (
              <div key={step.step} style={{display:"flex",alignItems:"center",flex:1,minWidth:100}}>
                <div onClick={function(){setSelStep(isSelected?null:step.step);}}
                  style={{display:"flex",flexDirection:"column",alignItems:"center",
                    cursor:"pointer",padding:"8px 4px",flex:1}}>
                  <div style={{width:56,height:56,borderRadius:"50%",
                    background:isSelected?C.acc:"#3B9EFF18",
                    border:"3px solid "+(isSelected?C.acc:"#3B9EFF50"),
                    display:"flex",flexDirection:"column",
                    alignItems:"center",justifyContent:"center",marginBottom:6,
                    boxShadow:isSelected?"0 0 0 4px "+C.acc+"30":"none"}}>
                    <span style={{fontSize:18,lineHeight:1}}>{step.icon}</span>
                    <span style={{color:isSelected?"#fff":"#3B9EFF",
                      fontSize:9,fontWeight:800}}>{step.step}</span>
                  </div>
                  <div style={{color:isSelected?C.acc:C.text,fontSize:10,fontWeight:700,
                    textAlign:"center",lineHeight:1.3,maxWidth:80}}>{step.name}</div>
                  <div style={{color:C.muted,fontSize:8,textAlign:"center",marginTop:2}}>
                    {step.actor}
                  </div>
                </div>
                {i<CLAIM_LIFECYCLE.length-1&&(
                  <div style={{display:"flex",alignItems:"center",flexShrink:0,width:20,marginTop:-20}}>
                    <div style={{flex:1,height:2,background:C.border}}/>
                    <span style={{color:C.muted,fontSize:10}}>▶</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Step detail */}
      {selStep&&(function(){
        var step=CLAIM_LIFECYCLE.find(function(s){return s.step===selStep;});
        return (
          <Card style={{marginBottom:14,border:"2px solid #3B9EFF30"}}>
            <div style={{display:"flex",gap:12,alignItems:"flex-start",marginBottom:12}}>
              <span style={{fontSize:28}}>{step.icon}</span>
              <div>
                <h3 style={{color:C.text,fontSize:15,fontWeight:800,margin:"0 0 3px"}}>
                  Step {step.step}: {step.name}
                </h3>
                <span style={{color:"#3B9EFF",fontSize:10,fontWeight:700,
                  background:"#3B9EFF14",borderRadius:4,padding:"1px 7px"}}>{step.actor}</span>
              </div>
            </div>
            <p style={{color:C.text,fontSize:12,lineHeight:1.7,margin:"0 0 12px"}}>{step.desc}</p>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              <div>
                <div style={{color:C.muted,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:5}}>
                  Data Created
                </div>
                <div style={{color:"#EF4545",fontSize:11,padding:"6px 10px",
                  background:"#EF454508",borderRadius:6,border:"1px solid #EF454520"}}>
                  {step.dataCreated}
                </div>
              </div>
              <div>
                <div style={{color:C.muted,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:5}}>
                  Systems Involved
                </div>
                <div style={{display:"flex",gap:4,flexWrap:"wrap"}}>
                  {step.systems.map(function(s){
                    return (
                      <span key={s} style={{color:C.acc,fontSize:10,background:C.faint,
                        borderRadius:4,padding:"2px 7px"}}>{s}</span>
                    );
                  })}
                </div>
              </div>
            </div>
          </Card>
        );
      })()}

      {/* PHI flow risk table */}
      <Card>
        <SH label="PHI Exposure at Each Stage"/>
        <div style={{display:"grid",gridTemplateColumns:"1fr 2fr 1fr",gap:0}}>
          <div style={{color:C.muted,fontSize:9,fontWeight:700,textTransform:"uppercase",padding:"6px 8px",background:C.dim,borderRadius:"6px 0 0 0"}}>Stage</div>
          <div style={{color:C.muted,fontSize:9,fontWeight:700,textTransform:"uppercase",padding:"6px 8px",background:C.dim}}>PHI / Data at Risk</div>
          <div style={{color:C.muted,fontSize:9,fontWeight:700,textTransform:"uppercase",padding:"6px 8px",background:C.dim,borderRadius:"0 6px 0 0"}}>Risk Level</div>
          {[
            {stage:"Enrollment",      data:"SSN, DOB, address, benefit elections",           risk:"High"},
            {stage:"Eligibility Check",data:"Member ID, coverage details, diagnosis history", risk:"High"},
            {stage:"Claim Creation",  data:"Full PHI: CPT, ICD, billed charges, provider",   risk:"Critical"},
            {stage:"EDI Submission",  data:"PHI in transit via clearinghouse",               risk:"Critical"},
            {stage:"Adjudication",    data:"Complete claims data at NASCO + vendors",        risk:"Critical"},
            {stage:"Payment",         data:"PHI on EOB + financial data to member",          risk:"High"},
            {stage:"Member Billing",  data:"PHI + financial in member portal",               risk:"Medium"},
          ].map(function(row,i){
            var color = row.risk==="Critical"?"#EF4545":row.risk==="High"?"#F5A623":"#3B9EFF";
            return (
              <React.Fragment key={row.stage}>
                <div style={{color:C.text,fontSize:11,fontWeight:600,padding:"7px 8px",
                  background:i%2===0?C.bg:C.card,borderBottom:"1px solid "+C.dim}}>{row.stage}</div>
                <div style={{color:C.muted,fontSize:10,padding:"7px 8px",
                  background:i%2===0?C.bg:C.card,borderBottom:"1px solid "+C.dim,lineHeight:1.4}}>{row.data}</div>
                <div style={{padding:"7px 8px",background:i%2===0?C.bg:C.card,
                  borderBottom:"1px solid "+C.dim}}>
                  <span style={{color:color,fontSize:9,fontWeight:800,background:color+"14",
                    borderRadius:3,padding:"1px 6px"}}>{row.risk}</span>
                </div>
              </React.Fragment>
            );
          })}
        </div>
      </Card>
    </div>
  );
}



