function getMidnightEST() {
  var now  = new Date();
  var et   = new Date(now.toLocaleString("en-US",{timeZone:"America/New_York"}));
  var midnight = new Date(et);
  midnight.setDate(midnight.getDate()+1);
  midnight.setHours(0,0,0,0);
  var diffLocal = midnight - et;
  return diffLocal;
}

