// ── QuickVoicePicker — standalone voice selector for pre-setup screens ────────
// Reads/writes the same localStorage keys as BrianaBar so settings persist
function QuickVoicePicker() {
  var LS = window.localStorage || { getItem:function(){return null;}, setItem:function(){}, removeItem:function(){} };
  var _sp  = useState(false);  var open=_sp[0];     var setOpen=_sp[1];

  // All voice state — initialised from localStorage, kept in sync
  var _svp = useState(LS.getItem("cx_voice_provider")||"browser");
  var provider=_svp[0]; var setProvider=_svp[1];
  var _svm = useState(LS.getItem("cx_voice_model")||"nova");
  var model=_svm[0];    var setModel=_svm[1];
  var _sok = useState(LS.getItem("cx_tts_key")||"");
  var oaiKey=_sok[0];   var setOaiKey=_sok[1];
  var _sek = useState(LS.getItem("cx_el_key")||"");
  var elKey=_sek[0];    var setElKey=_sek[1];
  var _sbv = useState(LS.getItem("cx_browser_voice")||"");
  var bVoice=_sbv[0];   var setBVoice=_sbv[1];
  var _sav = useState([]); var availVoices=_sav[0]; var setAvailVoices=_sav[1];
  var _sprev = useState("idle"); var prevState=_sprev[0]; var setPrevState=_sprev[1];

  // Re-read localStorage whenever panel opens (picks up changes from other pickers)
  useEffect(function(){
    if (!open) return;
    setProvider(LS.getItem("cx_voice_provider")||"browser");
    setModel(LS.getItem("cx_voice_model")||"nova");
    setOaiKey(LS.getItem("cx_tts_key")||"");
    setElKey(LS.getItem("cx_el_key")||"");
    setBVoice(LS.getItem("cx_browser_voice")||"");
  }, [open]);

  // Load browser voices
  useEffect(function(){
    function load(){
      var vv=window.speechSynthesis&&window.speechSynthesis.getVoices()||[];
      var SKIP=["Alex","Zarvox","Fred","Whisper","Trinoids","Boing","Bahh","Cellos","Superstar","Wobble","Bells"];
      setAvailVoices(vv.filter(function(v){
        return (v.lang||"").indexOf("en")===0 && SKIP.every(function(s){return (v.name||"").indexOf(s)<0;});
      }).sort(function(a,b){
        var sc=function(v){var n=v.name||"";return n.indexOf("Natural")>=0?0:n.indexOf("Enhanced")>=0?1:2;};
        return sc(a)-sc(b);
      }));
    }
    load();
    if(window.speechSynthesis){window.speechSynthesis.onvoiceschanged=load;}
    return function(){if(window.speechSynthesis){window.speechSynthesis.onvoiceschanged=null;}};
  },[]);

  // Persist helpers
  function pickProvider(p){ setProvider(p); LS.setItem("cx_voice_provider",p); }
  function pickModel(m)   { setModel(m);    LS.setItem("cx_voice_model",m); }

  // Preview — plays a short sample; shows real error message on failure
  var _serr = useState(""); var errMsg=_serr[0]; var setErrMsg=_serr[1];

  function playAudioBlob(blob){
    var url=URL.createObjectURL(blob);
    var a=new Audio(url);
    a.onended=function(){setPrevState("done");URL.revokeObjectURL(url);};
    a.onerror=function(e){setPrevState("error");setErrMsg("Audio playback failed");};
    var p=a.play();
    if(p){
      p.then(function(){setPrevState("playing");})
       .catch(function(e){
         setPrevState("error");
         setErrMsg("Playback blocked: "+e.message);
       });
    } else { setPrevState("playing"); }
  }

  function preview(){
    setErrMsg("");
    setPrevState("loading");
    var EL_IDS={"Rachel":"21m00Tcm4TlvDq8ikWAM","Charlotte":"XB0fDUnXU5powFXDhCwa",
      "Elli":"MF3mGyEYCl7XYWbV9V6O","Bella":"EXAVITQu4vr4xnSDxMaL",
      "Domi":"AZnzlk1XvdvUeBnXmlld","Antoni":"ErXwobaYiN019PkySvjV",
      "Josh":"TxGEqnHWrfWFTfGW9XjX","Adam":"pNInz6obpgDQGcFmaJgB",
      "Sam":"yoZ06aMxZJJ28mfd3POQ","Callum":"N2lVS1w4EtoT3dr4eOWO"};
    var SAMPLE = "Hi, I'm Briana. I'll guide you through your CyberRx setup.";

    if(provider==="elevenlabs"){
      if(!elKey){ setPrevState("no_key"); setErrMsg("Paste your ElevenLabs key above first"); return; }
      fetch("https://api.elevenlabs.io/v1/text-to-speech/"+(EL_IDS[model]||EL_IDS["Rachel"]),{
        method:"POST",
        headers:{"xi-api-key":elKey,"Content-Type":"application/json","Accept":"audio/mpeg"},
        body:JSON.stringify({text:SAMPLE,model_id:"eleven_turbo_v2_5",
          voice_settings:{stability:0.40,similarity_boost:0.82,style:0.12,use_speaker_boost:true}})
      }).then(function(r){
        if(!r.ok){ return r.text().then(function(t){ throw new Error("HTTP "+r.status+": "+t.slice(0,120)); }); }
        return r.blob();
      }).then(function(b){ playAudioBlob(b); })
      .catch(function(e){
        var msg = e.message||String(e);
        // CSP/network block looks like TypeError: Failed to fetch
        if(msg.indexOf("fetch")>=0||msg.indexOf("NetworkError")>=0||msg.indexOf("blocked")>=0){
          msg = "Network blocked — ElevenLabs works when the app is deployed outside Claude.ai. Use Browser tab here.";
        }
        setPrevState("error"); setErrMsg(msg);
      });
      return;
    }

    if(provider==="openai"){
      if(!oaiKey||!oaiKey.startsWith("sk-")){ setPrevState("no_key"); setErrMsg("Paste your OpenAI sk- key above first"); return; }
      fetch("https://api.openai.com/v1/audio/speech",{
        method:"POST",
        headers:{"Authorization":"Bearer "+oaiKey,"Content-Type":"application/json"},
        body:JSON.stringify({model:"tts-1-hd",voice:model||"nova",input:SAMPLE,speed:0.92})
      }).then(function(r){
        if(!r.ok){ return r.text().then(function(t){ throw new Error("HTTP "+r.status+": "+t.slice(0,120)); }); }
        return r.blob();
      }).then(function(b){ playAudioBlob(b); })
      .catch(function(e){
        var msg = e.message||String(e);
        if(msg.indexOf("fetch")>=0||msg.indexOf("NetworkError")>=0||msg.indexOf("blocked")>=0){
          msg = "Network blocked — OpenAI TTS works when deployed outside Claude.ai. Use Browser tab here.";
        }
        setPrevState("error"); setErrMsg(msg);
      });
      return;
    }

    // Browser TTS — always works
    if(!window.speechSynthesis){ setPrevState("error"); setErrMsg("Browser TTS not supported"); return; }
    window.speechSynthesis.cancel();
    var u=new SpeechSynthesisUtterance(SAMPLE);
    u.rate=0.86; u.pitch=1.0;
    u.onend=function(){setPrevState("done");};
    u.onerror=function(e){setPrevState("error");setErrMsg("Speech error: "+(e.error||"unknown"));};
    var vv=window.speechSynthesis.getVoices();
    var pref=bVoice?vv.find(function(v){return v.name===bVoice;}):null;
    if(!pref){
      var PRI=["Microsoft Aria Online (Natural) - English (United States)",
        "Microsoft Jenny Online (Natural) - English (United States)",
        "Samantha (Enhanced)","Google US English","Samantha"];
      for(var pi=0;pi<PRI.length;pi++){var pv=vv.find(function(v){return v.name===PRI[pi];}); if(pv){pref=pv;break;}}
    }
    if(pref){u.voice=pref;}
    window.speechSynthesis.speak(u);
    setPrevState("playing");
  }

  var COLORS={browser:C.acc, openai:"#0FBB80", elevenlabs:"#A78BFA"};
  var ac = COLORS[provider]||C.acc;
  var hasKey = provider==="elevenlabs"?!!elKey : provider==="openai"?oaiKey.startsWith("sk-") : true;

  var btnLabel = provider==="elevenlabs"&&elKey ? "ElevenLabs · "+model
    : provider==="openai"&&oaiKey.startsWith("sk-") ? "OpenAI · "+model
    : bVoice ? bVoice.replace("Microsoft ","").replace(" Online (Natural)","").split(" - ")[0]
    : "Choose Voice";

  var prevLabel = prevState==="loading"?"Loading…":prevState==="playing"?"Playing…":
    prevState==="done"?"✓ Preview played":prevState==="no_key"?"⚠ Enter API key first":
    prevState==="error"?"✕ Error — check key/network":"▶  Preview voice";

  return (
    <div style={{position:"relative"}}>
      <button onClick={function(){setOpen(!open); setPrevState("idle");}}
        style={{display:"flex",alignItems:"center",gap:6,
          background:open?ac+"18":"transparent",
          border:"1.5px solid "+(open?ac:C.border),
          color:open?ac:C.text,
          borderRadius:8,padding:"7px 13px",cursor:"pointer",fontSize:11,fontWeight:600,
          transition:"all 0.15s"}}>
        <span style={{fontSize:14}}>🎙</span>
        <span>{btnLabel}</span>
        <span style={{fontSize:9,opacity:0.5}}>{open?"▲":"▼"}</span>
      </button>

      {open&&(
        <div style={{position:"absolute",top:"calc(100% + 8px)",right:0,zIndex:9999,
          background:C.panel,border:"1px solid "+C.border,borderRadius:14,
          padding:"16px",width:340,
          boxShadow:"0 8px 40px rgba(0,0,0,0.18)"}}>

          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
            <div style={{fontSize:11,fontWeight:700,color:C.text}}>🎙 Choose Briana's voice</div>
            <button onClick={function(){setOpen(false);}}
              style={{background:"transparent",border:"none",color:C.muted,
                cursor:"pointer",fontSize:16,padding:"0 4px"}}>×</button>
          </div>

          {/* Provider tabs */}
          <div style={{display:"flex",gap:4,marginBottom:12}}>
            {[{id:"browser",icon:"🌐",label:"Browser",sub:"Free"},
              {id:"openai", icon:"⚡",label:"OpenAI", sub:"Needs key"},
              {id:"elevenlabs",icon:"✨",label:"ElevenLabs",sub:"Best quality"}
            ].map(function(p){
              var act=provider===p.id;
              var pc=COLORS[p.id];
              return (
                <button key={p.id} onClick={function(){pickProvider(p.id); setPrevState("idle");}}
                  style={{flex:1,border:"1.5px solid "+(act?pc:C.border),
                    background:act?pc+"18":"transparent",
                    borderRadius:8,padding:"6px 4px",cursor:"pointer",textAlign:"center",
                    transition:"all 0.12s"}}>
                  <div style={{fontSize:13}}>{p.icon}</div>
                  <div style={{fontSize:10,fontWeight:700,color:act?pc:C.text,marginTop:1}}>{p.label}</div>
                  <div style={{fontSize:8,color:C.muted}}>{p.sub}</div>
                </button>
              );
            })}
          </div>

          {/* Browser voices */}
          {provider==="browser"&&(
            <select value={bVoice}
              onChange={function(e){setBVoice(e.target.value);LS.setItem("cx_browser_voice",e.target.value);}}
              style={{width:"100%",background:C.bg,border:"1px solid "+C.border,
                borderRadius:7,padding:"7px 9px",color:C.text,fontSize:10,outline:"none",
                boxSizing:"border-box",marginBottom:8}}>
              <option value="">Auto — best available</option>
              {availVoices.map(function(v){
                return <option key={v.name} value={v.name}>{v.name}</option>;
              })}
            </select>
          )}

          {/* OpenAI voices */}
          {provider==="openai"&&(
            <div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:5,marginBottom:10}}>
                {[{id:"nova",l:"Nova",d:"Warm"},
                  {id:"shimmer",l:"Shimmer",d:"Soft"},
                  {id:"alloy",l:"Alloy",d:"Neutral"},
                  {id:"echo",l:"Echo",d:"Resonant"},
                  {id:"onyx",l:"Onyx",d:"Deep"},
                  {id:"fable",l:"Fable",d:"Expressive"},
                ].map(function(v){
                  var act=model===v.id;
                  return (
                    <button key={v.id} onClick={function(){pickModel(v.id);}}
                      style={{border:"1px solid "+(act?"#0FBB80":C.border),
                        background:act?"#0FBB8018":"transparent",
                        borderRadius:7,padding:"6px 4px",cursor:"pointer",textAlign:"center"}}>
                      <div style={{fontSize:10,fontWeight:act?700:500,color:act?"#0FBB80":C.text}}>{v.l}</div>
                      <div style={{fontSize:8,color:C.muted}}>{v.d}</div>
                    </button>
                  );
                })}
              </div>
              <input type="password" placeholder="sk-…  OpenAI API key"
                value={oaiKey}
                onChange={function(e){
                  var k=e.target.value;
                  setOaiKey(k);
                  LS.setItem("cx_tts_key",k);
                }}
                style={{width:"100%",background:C.bg,
                  border:"1.5px solid "+(oaiKey.startsWith("sk-")?"#0FBB80":C.border),
                  borderRadius:7,padding:"7px 9px",fontSize:10,color:C.text,
                  outline:"none",boxSizing:"border-box"}}/>
              {oaiKey.startsWith("sk-")&&<div style={{color:"#0FBB80",fontSize:9,marginTop:4}}>✓ Key active</div>}
            </div>
          )}

          {/* ElevenLabs voices */}
          {provider==="elevenlabs"&&(
            <div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:5,marginBottom:10}}>
                {[{id:"Rachel",d:"Calm · American"},
                  {id:"Charlotte",d:"Confident · British"},
                  {id:"Elli",d:"Bright · upbeat"},
                  {id:"Bella",d:"Gentle · warm"},
                  {id:"Domi",d:"Strong female"},
                  {id:"Antoni",d:"Natural male"},
                  {id:"Josh",d:"Deep male"},
                  {id:"Callum",d:"Narrator"},
                ].map(function(v){
                  var act=model===v.id;
                  return (
                    <button key={v.id} onClick={function(){pickModel(v.id);}}
                      style={{border:"1px solid "+(act?"#A78BFA":C.border),
                        background:act?"#A78BFA18":"transparent",
                        borderRadius:7,padding:"6px 8px",cursor:"pointer",
                        display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                      <span style={{fontSize:10,fontWeight:act?700:500,color:act?"#A78BFA":C.text}}>{v.id}</span>
                      <span style={{fontSize:8,color:C.muted}}>{v.d}</span>
                    </button>
                  );
                })}
              </div>
              <input type="password" placeholder="ElevenLabs API key (sk_…)"
                value={elKey}
                onChange={function(e){
                  var k=e.target.value;
                  setElKey(k);
                  LS.setItem("cx_el_key",k);
                }}
                style={{width:"100%",background:C.bg,
                  border:"1.5px solid "+(elKey?"#A78BFA":C.border),
                  borderRadius:7,padding:"7px 9px",fontSize:10,color:C.text,
                  outline:"none",boxSizing:"border-box"}}/>
              {elKey&&<div style={{color:"#A78BFA",fontSize:9,marginTop:4}}>✓ Key active</div>}
            </div>
          )}

          {/* Preview button */}
          <button onClick={preview} disabled={prevState==="loading"||prevState==="playing"}
            style={{width:"100%",marginTop:10,
              background:prevState==="done"?"#0FBB8018":prevState==="error"||prevState==="no_key"?"#EF454518":ac+"18",
              border:"1px solid "+(prevState==="done"?"#0FBB80":prevState==="error"||prevState==="no_key"?"#EF4545":ac+"50"),
              color:prevState==="done"?"#0FBB80":prevState==="error"||prevState==="no_key"?"#EF4545":ac,
              borderRadius:8,padding:"8px",cursor:prevState==="loading"||prevState==="playing"?"wait":"pointer",
              fontSize:11,fontWeight:600,transition:"all 0.15s"}}>
            {prevLabel}
          </button>

          {errMsg&&(
            <div style={{marginTop:6,padding:"6px 10px",borderRadius:6,
              background:"#EF454510",border:"1px solid #EF454530",
              fontSize:9,color:"#EF4545",lineHeight:1.5,wordBreak:"break-word"}}>
              {errMsg}
            </div>
          )}
          <div style={{fontSize:9,color:C.muted,marginTop:8,textAlign:"center",lineHeight:1.5}}>
            Settings save automatically · used throughout the app
          </div>
        </div>
      )}
    </div>
  );
}


function WelcomePage(props) {
  var onStartSetup    = props.onStartSetup    || function(){};
  var onGoToDashboard = props.onGoToDashboard || function(){};
  var setupDone       = !!props.setupDone;
  var orgName         = props.orgName;

  return (
    <div style={{minHeight:"100vh",background:C.bg,color:C.text,
      display:"flex",flexDirection:"column"}}>

      {/* ── NAV ── */}
      <div style={{padding:"16px 40px",display:"flex",alignItems:"center",
        justifyContent:"space-between",borderBottom:"1px solid "+C.border,
        position:"sticky",top:0,background:C.bg,zIndex:10}}>
        <div style={{display:"flex",alignItems:"center",gap:9}}>
          <div style={{width:34,height:34,borderRadius:10,
            background:"linear-gradient(135deg,#00C4A0,#0090F0)",
            display:"flex",alignItems:"center",justifyContent:"center"}}>
            <span style={{color:"#000",fontWeight:900,fontSize:15}}>Rx</span>
          </div>
          <span style={{color:C.text,fontWeight:800,fontSize:17,
            letterSpacing:"-0.02em"}}>CyberRx</span>
          <span style={{color:C.muted,fontSize:11,background:C.dim,
            borderRadius:10,padding:"2px 8px",marginLeft:4}}>
            Healthcare Payer Edition
          </span>
        </div>
        <div style={{display:"flex",gap:10,alignItems:"center"}}>
          {orgName&&(
            <span style={{color:C.muted,fontSize:12}}>
              Signed in{" · "}<strong style={{color:C.text}}>{orgName}</strong>
            </span>
          )}
          <QuickVoicePicker/>
          <button onClick={setupDone?onGoToDashboard:onStartSetup}
            style={{background:C.acc,border:"none",color:"#fff",borderRadius:8,
              padding:"8px 20px",cursor:"pointer",fontSize:13,fontWeight:700,
              boxShadow:"0 0 16px "+C.acc+"40"}}>
            {setupDone?"Go to Dashboard →":"Start Assessment →"}
          </button>
        </div>
      </div>

      {/* ── HERO ── */}
      <div style={{textAlign:"center",padding:"56px 24px 48px",
        maxWidth:720,margin:"0 auto"}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:8,
          background:"linear-gradient(90deg,"+C.acc+"20,#A78BFA20)",
          border:"1px solid "+C.acc+"35",borderRadius:20,
          padding:"5px 16px",marginBottom:22}}>
          <div style={{width:6,height:6,borderRadius:"50%",background:C.acc,
            boxShadow:"0 0 8px "+C.acc}}/>
          <span style={{color:C.acc,fontSize:11,fontWeight:700,letterSpacing:"0.09em"}}>
            EXECUTIVE CYBER RESPONSIBILITY PLATFORM
          </span>
        </div>
        <h1 style={{color:C.text,fontSize:46,fontWeight:900,lineHeight:1.08,
          margin:"0 0 18px",letterSpacing:"-0.02em"}}>
          Translate cyber technical data into<br/>
          <span style={{background:"linear-gradient(90deg,"+C.acc+",#A78BFA)",
            WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",
            backgroundClip:"text"}}>business impact so executives can protect their organization.</span>
        </h1>
        <p style={{color:C.muted,fontSize:15,lineHeight:1.75,margin:"0 0 28px",
          maxWidth:540,marginLeft:"auto",marginRight:"auto"}}>
          CyberRx translates security findings into executive narratives showing business process impact,
          financial exposure, regulatory obligations, and ownership — so C-level leaders can make informed
          decisions about their cyber responsibilities in one platform.
        </p>
      </div>

      {/* ── THE THREE-COLUMN CORE ── */}
      <div style={{background:C.panel,borderTop:"1px solid "+C.border,
        borderBottom:"1px solid "+C.border,padding:"52px 32px"}}>
        <div style={{maxWidth:1040,margin:"0 auto"}}>

          {/* How it works — step-by-step journey */}
          <div style={{textAlign:"center",marginBottom:28}}>
            <p style={{color:C.muted,fontSize:11,fontWeight:700,
              letterSpacing:"0.1em",textTransform:"uppercase",marginBottom:8}}>
              How it works
            </p>
            <h2 style={{color:C.text,fontSize:26,fontWeight:900,
              margin:"0 0 8px",letterSpacing:"-0.02em"}}>
              From zero to live risk intelligence in 6 steps
            </h2>
            <p style={{color:C.muted,fontSize:13,maxWidth:460,margin:"0 auto",lineHeight:1.6}}>
              Set up once. CyberRx does the rest — automatically connecting your environment
              and generating live dashboards for every executive audience.
            </p>
          </div>

          {/* Step flow */}
          <div style={{display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:8,marginBottom:32}}>
            {[
              {n:"1",icon:"🏥",color:"#3B9EFF",
               title:"Set Up Your Organization",
               desc:"Answer a few foundation questions — org type, revenue, PHI record count, statutory surplus, and insurance details."},
              {n:"2",icon:"🗄",color:"#A78BFA",
               title:"Import Your Applications",
               desc:"Import your business application inventory from your CMDB, a CSV/Excel export, or via REST API. CyberRx maps each app to its business process automatically."},
              {n:"3",icon:"🔌",color:"#F5A623",
               title:"Connect Your Infrastructure",
               desc:"Link CyberRx to your security tools via API or connector — endpoint, identity, SIEM, network, cloud, and GRC. Evidence flows in automatically."},
              {n:"4",icon:"📋",color:"#EF4545",
               title:"Upload Key Documents",
               desc:"Upload your existing security policies and procedures. CyberRx AI validates each document against its required control attributes."},
              {n:"5",icon:"⚡",color:"#0FBB80",
               title:"Launch Risk Intelligence",
               desc:"CyberRx analyzes your environment, tests every control against live evidence, and populates your compliance reports and financial exposure models."},
              {n:"6",icon:"📊",color:"#8B5CF6",
               title:"View Your Results",
               desc:"Your CISO, CRO, CFO, and Board dashboards are live. Every finding is traced to its business process, dollar impact, and regulatory consequence."},
            ].map(function(step, i){
              return (
                <div key={i} style={{background:C.card,
                  border:"1px solid "+step.color+"25",
                  borderTop:"3px solid "+step.color,
                  borderRadius:10,padding:"14px 12px",position:"relative"}}>
                  <div style={{display:"flex",gap:7,alignItems:"center",marginBottom:8}}>
                    <div style={{width:22,height:22,borderRadius:"50%",
                      background:step.color,display:"flex",alignItems:"center",
                      justifyContent:"center",flexShrink:0}}>
                      <span style={{color:"#fff",fontSize:10,fontWeight:800}}>{step.n}</span>
                    </div>
                    <span style={{fontSize:16}}>{step.icon}</span>
                  </div>
                  <div style={{color:step.color,fontSize:10,fontWeight:800,
                    marginBottom:4,lineHeight:1.3}}>{step.title}</div>
                  <div style={{color:C.muted,fontSize:8,lineHeight:1.5}}>{step.desc}</div>
                </div>
              );
            })}
          </div>

          {/* Three-column data flow */}
          <div style={{textAlign:"center",marginBottom:20}}>
            <p style={{color:C.muted,fontSize:11,fontWeight:700,
              letterSpacing:"0.1em",textTransform:"uppercase",marginBottom:6}}>
              Under the hood
            </p>
            <p style={{color:C.muted,fontSize:12,maxWidth:460,margin:"0 auto",lineHeight:1.6}}>
              CyberRx sits between your security environment and your compliance reports —
              drawing evidence directly, so every report reflects what is actually happening.
            </p>
          </div>

          {/* THREE COLUMNS */}
          <div style={{display:"grid",gridTemplateColumns:"1fr auto 1fr",
            gap:16,alignItems:"start"}}>

            {/* ── LEFT: Security Infrastructure ── */}
            <div>
              <div style={{color:"#3B9EFF",fontSize:10,fontWeight:700,
                textTransform:"uppercase",letterSpacing:"0.08em",
                marginBottom:10,textAlign:"center"}}>
                Your Security Environment
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:6}}>
                {[
                  {icon:"🛡",cat:"Endpoint Security",
                   ex:"EDR · XDR · AV",color:"#3B9EFF"},
                  {icon:"🔑",cat:"Identity & Access",
                   ex:"MFA · SSO · PAM",color:"#A78BFA"},
                  {icon:"📡",cat:"SIEM & Monitoring",
                   ex:"Log aggregation · Alerting",color:"#F5A623"},
                  {icon:"🗄",cat:"CMDB & Asset Mgmt",
                   ex:"Software · Hardware · Cloud",color:"#EF4545"},
                  {icon:"🌐",cat:"Network & Perimeter",
                   ex:"Firewall · NGFW · Zero Trust",color:"#0891B2"},
                  {icon:"☁",cat:"Cloud Security",
                   ex:"CSPM · CWPP · CIEM",color:"#0FBB80"},
                  {icon:"📋",cat:"GRC & Ticketing",
                   ex:"Risk register · Change mgmt",color:"#8B5CF6"},
                  {icon:"📧",cat:"Email & Phishing",
                   ex:"Simulation · Gateway · DLP",color:"#EC4899"},
                ].map(function(src){
                  return (
                    <div key={src.cat} style={{display:"flex",gap:10,
                      alignItems:"center",background:C.card,
                      border:"1px solid "+src.color+"25",
                      borderLeft:"3px solid "+src.color,
                      borderRadius:8,padding:"9px 12px"}}>
                      <span style={{fontSize:16,flexShrink:0}}>{src.icon}</span>
                      <div style={{flex:1}}>
                        <div style={{color:src.color,fontSize:10,fontWeight:700}}>
                          {src.cat}
                        </div>
                        <div style={{color:C.muted,fontSize:8,lineHeight:1.3}}>
                          {src.ex}
                        </div>
                      </div>
                      <div style={{width:7,height:7,borderRadius:"50%",
                        background:"#0FBB80",flexShrink:0,
                        boxShadow:"0 0 6px #0FBB8080"}}/>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* ── CENTER: CyberRx Engine ── */}
            <div style={{display:"flex",flexDirection:"column",
              alignItems:"center",justifyContent:"center",
              padding:"20px 8px",minWidth:120}}>

              {/* Flow arrows + engine */}
              <div style={{color:C.acc,fontSize:20,marginBottom:6}}>&#x21e8;</div>

              <div style={{background:"linear-gradient(135deg,"+C.acc+",#A78BFA)",
                borderRadius:16,padding:"20px 16px",textAlign:"center",
                boxShadow:"0 0 40px "+C.acc+"35",marginBottom:6}}>
                <div style={{width:52,height:52,borderRadius:14,
                  background:"linear-gradient(135deg,#00C4A0,#0090F0)",
                  display:"flex",alignItems:"center",justifyContent:"center",
                  margin:"0 auto 10px",
                  boxShadow:"0 0 20px #00C4A050"}}>
                  <span style={{color:"#000",fontWeight:900,fontSize:20}}>Rx</span>
                </div>
                <div style={{color:"#fff",fontSize:12,fontWeight:800,
                  letterSpacing:"0.03em",marginBottom:4}}>CyberRx</div>
                <div style={{color:"rgba(255,255,255,0.75)",fontSize:9,
                  lineHeight:1.5}}>Evidence<br/>Engine</div>
              </div>

              <div style={{color:C.acc,fontSize:20,marginTop:6}}>&#x21e8;</div>

              <div style={{marginTop:10,textAlign:"center"}}>
                <div style={{color:C.acc,fontSize:9,fontWeight:600,
                  background:C.acc+"12",border:"1px solid "+C.acc+"30",
                  borderRadius:6,padding:"4px 10px",lineHeight:1.5}}>
                  Evidence-based<br/>not self-attestation
                </div>
              </div>
            </div>

            {/* ── RIGHT: Framework Reports ── */}
            <div>
              <div style={{color:"#0FBB80",fontSize:10,fontWeight:700,
                textTransform:"uppercase",letterSpacing:"0.08em",
                marginBottom:10,textAlign:"center"}}>
                Auto-Generated Reports
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:6}}>
                {[
                  {fw:"HIPAA Security Rule",         ref:"45 CFR Part 164",
                   badge:"All Payers",color:"#EF4545"},
                  {fw:"NIST CSF 2.0",               ref:"HHS HPH CPG 2024",
                   badge:"All Payers",color:"#F5A623"},
                  {fw:"NIST SP 800-53 Rev 5",        ref:"OCR Referenced",
                   badge:"All Payers",color:"#F5A623"},
                  {fw:"CIS Controls v8",             ref:"HHS IG2 Benchmark",
                   badge:"All Payers",color:"#3B9EFF"},
                  {fw:"NAIC Model Law",              ref:"24+ States",
                   badge:"All Payers",color:"#A78BFA"},
                  {fw:"ISO/IEC 27001:2022",          ref:"BAA & DOI Standard",
                   badge:"All Payers",color:"#0FBB80"},
                  {fw:"PCI DSS v4.0",               ref:"Card Payments",
                   badge:"If Applicable",color:"#0891B2"},
                  {fw:"CMS 42 CFR §422/§423",ref:"MA / Part D",
                   badge:"If Applicable",color:"#8B5CF6"},
                ].map(function(fw){
                  var req = fw.badge === "All Payers";
                  return (
                    <div key={fw.fw} style={{display:"flex",gap:10,
                      alignItems:"center",background:C.card,
                      border:"1px solid "+fw.color+"25",
                      borderRight:"3px solid "+fw.color,
                      borderRadius:8,padding:"9px 12px"}}>
                      <span style={{color:"#0FBB80",fontSize:12,flexShrink:0}}>
                        &#x2713;
                      </span>
                      <div style={{flex:1}}>
                        <div style={{color:fw.color,fontSize:10,fontWeight:700}}>
                          {fw.fw}
                        </div>
                        <div style={{color:C.muted,fontSize:8}}>{fw.ref}</div>
                      </div>
                      <span style={{color:req?"#0FBB80":"#F5A623",fontSize:7,
                        fontWeight:700,background:req?"#0FBB8014":"#F5A62314",
                        borderRadius:3,padding:"1px 5px",flexShrink:0,
                        whiteSpace:"nowrap"}}>
                        {fw.badge}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

          </div>
        </div>
      </div>

      {/* ── CTA ── */}
      <div style={{flex:1,display:"flex",flexDirection:"column",
        alignItems:"center",justifyContent:"center",
        background:"linear-gradient(135deg,"+C.acc+"10,#A78BFA08,"+C.bg+")",
        borderTop:"1px solid "+C.border,padding:"56px 24px",textAlign:"center"}}>
        <h2 style={{color:C.text,fontSize:28,fontWeight:900,
          margin:"0 0 14px",letterSpacing:"-0.02em"}}>
          {setupDone?
            "Your dashboards are ready.":
            "Ready to see your organization's risk in dollars?"
          }
        </h2>
        <p style={{color:C.muted,fontSize:14,lineHeight:1.7,
          margin:"0 0 32px",maxWidth:440}}>
          {setupDone?
            "Navigate to your live dashboards. All your data is saved.":
            "Complete the 7-step setup and your CISO, CFO, CRO, and Board dashboards populate automatically from your actual data."
          }
        </p>
        <button onClick={setupDone?onGoToDashboard:onStartSetup}
          style={{background:C.acc,border:"none",color:"#fff",borderRadius:12,
            padding:"16px 52px",cursor:"pointer",fontSize:16,fontWeight:800,
            boxShadow:"0 4px 28px "+C.acc+"50",letterSpacing:"-0.01em"}}>
          {setupDone?
            "Go to Command Center →":
            "Start Your Assessment →"
          }
        </button>
        <div style={{color:C.muted,fontSize:11,marginTop:12}}>
          {setupDone?
            "Pick up where you left off · All data saved":
            "HIPAA-aware · 30-minute setup · No credit card required"
          }
        </div>
      </div>

    </div>
  );
}




