var ADAPTER_TAB = {CONFIG:0, RAW:1, NORMALIZED:2, MAPPING:3};

function CyberRxAPIAdapter(props) {
  var go = props.go || function(){};

  var _s0=useState("okta");       var activeTool=_s0[0]; var setActiveTool=_s0[1];
  var _s1=useState(ADAPTER_TAB.CONFIG); var activeTab=_s1[0]; var setActiveTab=_s1[1];
  var _s2=useState({});            var pulled=_s2[0];      var setPulled=_s2[1];
  var _s3=useState(false);         var loading=_s3[0];     var setLoading=_s3[1];
  var _s4=useState(null);          var expandedFinding=_s4[0]; var setExpandedFinding=_s4[1];

  var tool      = MOCK_RESPONSES[activeTool];
  var hasPulled = !!(pulled[activeTool]);

  function runPull() {
    setLoading(true);
    setTimeout(function() {
      var n = Object.assign({}, pulled);
      n[activeTool] = true;
      setPulled(n);
      setLoading(false);
      setActiveTab(ADAPTER_TAB.NORMALIZED);
    }, 1400);
  }

  var allFindings = Object.keys(pulled).length > 0
    ? Object.keys(pulled).reduce(function(acc,k){ return acc.concat(MOCK_RESPONSES[k].normalized); },[])
    : [];

  var cisImpact = {};
  allFindings.forEach(function(f) {
    if (!cisImpact[f.cisControl]) { cisImpact[f.cisControl] = []; }
    cisImpact[f.cisControl].push(f);
  });

  var connectedCount  = Object.keys(pulled).length;
  var totalFindings   = allFindings.length;

  return (
    <div style={{fontFamily:"'Inter','Segoe UI',sans-serif",background:C.bg,
      minHeight:"100vh",color:C.text,fontSize:13}}>

      {/* Header */}
      <div style={{background:C.surface,borderBottom:"1px solid "+C.border,
        padding:"12px 24px",display:"flex",alignItems:"center",
        justifyContent:"space-between"}}>
        <div style={{display:"flex",gap:12,alignItems:"center"}}>
          <button onClick={function(){go("hub");}}
            style={{background:"transparent",border:"none",color:C.acc,
              cursor:"pointer",fontSize:11,fontWeight:700}}>
            &#x2190; Command Center
          </button>
          <span style={{color:C.border}}>|</span>
          <div>
            <div style={{fontSize:10,color:C.acc,letterSpacing:3,fontWeight:700}}>
              CYBERRX — MODULE F01
            </div>
            <div style={{fontSize:16,fontWeight:700}}>API Adapter Layer</div>
          </div>
        </div>
        <div style={{display:"flex",gap:8}}>
          {connectedCount > 0&&(
            <div style={{background:C.accDim,border:"1px solid "+C.acc+"40",
              borderRadius:8,padding:"5px 12px",fontSize:11,color:C.acc}}>
              {connectedCount} source{connectedCount>1?"s":""} connected
              &nbsp;&middot;&nbsp;{totalFindings} findings normalized
            </div>
          )}
          <div style={{background:"#1E2A3F",border:"1px solid "+C.border,
            borderRadius:8,padding:"5px 12px",fontSize:11,color:C.muted}}>
            Mock mode &#8212; sandbox data
          </div>
        </div>
      </div>

      <div style={{display:"flex",height:"calc(100vh - 57px)"}}>

        {/* Sidebar */}
        <div style={{width:180,background:C.surface,
          borderRight:"1px solid "+C.border,padding:"16px 0",flexShrink:0}}>
          <div style={{fontSize:10,color:C.muted,letterSpacing:2,
            padding:"0 16px 10px"}}>CONNECTORS</div>
          {TOOLS.map(function(t){
            var isActive = activeTool===t.key;
            // Check if this tool was connected via Setup Step 5
            var itsmMatch = Object.values(ITSM_SYSTEMS).find(function(s){
              return s.apiAdapterId===t.key;
            });
            var isSetupConnected = itsmMatch
              ? itsmMatch.toolKeys.some(function(k){ return !!_globalInfraSel[k]; })
              : false;
            return (
              <div key={t.key}
                onClick={function(){
                  setActiveTool(t.key);
                  setActiveTab(pulled[t.key]?ADAPTER_TAB.NORMALIZED:ADAPTER_TAB.CONFIG);
                }}
                style={{padding:"10px 16px",cursor:"pointer",
                  borderLeft:"2px solid "+(isActive?t.color:"transparent"),
                  background:isActive?"#1E2A3F":"transparent",
                  transition:"all 0.15s",display:"flex",alignItems:"center",gap:10}}>
                <span style={{fontSize:16,color:t.color}}>{t.icon}</span>
                <div>
                  <div style={{display:"flex",alignItems:"center",gap:5}}>
                    <span style={{fontSize:12,color:isActive?C.text:C.muted,
                      fontWeight:isActive?700:400}}>{t.label}</span>
                    {isSetupConnected&&(
                      <span style={{width:6,height:6,borderRadius:"50%",background:"#0FBB80",
                        display:"inline-block",flexShrink:0}} title="Connected via Setup Step 5"/>
                    )}
                  </div>
                  <div style={{fontSize:10,color:isSetupConnected?"#0FBB80":C.muted}}>
                    {t.sub}{isSetupConnected?" · configured":""}
                  </div>
                </div>
                {pulled[t.key]&&(
                  <div style={{marginLeft:"auto",width:7,height:7,
                    borderRadius:"50%",background:C.acc}}/>
                )}
              </div>
            );
          })}

          <div style={{borderTop:"1px solid "+C.border,margin:"16px 0 10px"}}/>
          <div style={{fontSize:10,color:C.muted,letterSpacing:2,
            padding:"0 16px 10px"}}>AGGREGATE</div>
          <div onClick={function(){setActiveTab(ADAPTER_TAB.MAPPING);}}
            style={{padding:"10px 16px",cursor:"pointer",
              background:activeTab===ADAPTER_TAB.MAPPING?"#1E2A3F":"transparent"}}>
            <div style={{fontSize:12,
              color:activeTab===ADAPTER_TAB.MAPPING?C.acc:C.muted}}>
              &#9672; Control Scores
            </div>
          </div>
        </div>

        {/* Main panel */}
        <div style={{flex:1,overflowY:"auto"}}>

          {/* Tabs */}
          {activeTab!==ADAPTER_TAB.MAPPING&&(
            <div style={{display:"flex",borderBottom:"1px solid "+C.border,
              background:C.surface}}>
              {[
                [ADAPTER_TAB.CONFIG,     "Configuration"],
                [ADAPTER_TAB.RAW,        "Raw API Response"],
                [ADAPTER_TAB.NORMALIZED, "Normalized Findings"],
              ].map(function(tabPair){
                var tabId=tabPair[0]; var tabLabel=tabPair[1];
                var isActive = activeTab===tabId;
                return (
                  <div key={tabId} onClick={function(){setActiveTab(tabId);}}
                    style={{padding:"12px 20px",fontSize:12,cursor:"pointer",
                      borderBottom:"2px solid "+(isActive?C.acc:"transparent"),
                      color:isActive?C.acc:C.muted,transition:"all 0.15s"}}>
                    {tabLabel}
                    {tabId===ADAPTER_TAB.NORMALIZED&&hasPulled&&(
                      <span style={{marginLeft:8,background:C.accDim,color:C.acc,
                        fontSize:10,padding:"1px 6px",borderRadius:10}}>
                        {tool.normalized.length}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {/* ── CONFIG TAB ── */}
          {activeTab===ADAPTER_TAB.CONFIG&&(
            <div style={{padding:24}}>
              <div style={{marginBottom:20}}>
                <div style={{fontSize:16,fontWeight:700,marginBottom:4}}>
                  {tool.label}
                </div>
                <div style={{fontSize:11,color:C.muted}}>
                  Connection configuration and what this adapter collects
                </div>
              </div>

              <div style={{background:C.card,border:"1px solid "+C.border,
                borderRadius:10,padding:20,marginBottom:16}}>
                <div style={{fontSize:11,color:C.acc,letterSpacing:2,marginBottom:14}}>
                  CONNECTION SETTINGS
                </div>
                {[
                  {label:"API Endpoint",    value:tool.endpoint},
                  {label:"Authentication",  value:tool.auth},
                ].map(function(field){
                  return (
                    <div key={field.label} style={{marginBottom:14}}>
                      <div style={{fontSize:11,color:C.muted,marginBottom:6}}>
                        {field.label}
                      </div>
                      <div style={{background:C.surface,border:"1px solid "+C.border,
                        borderRadius:6,padding:"8px 12px",fontSize:11,color:C.text,
                        wordBreak:"break-all",fontFamily:"monospace"}}>
                        {field.value}
                      </div>
                    </div>
                  );
                })}
              </div>

              <div style={{background:C.card,border:"1px solid "+C.border,
                borderRadius:10,padding:20,marginBottom:16}}>
                <div style={{fontSize:11,color:C.acc,letterSpacing:2,marginBottom:14}}>
                  DATA COLLECTED
                </div>
                {(tool.pulls||[]).map(function(p,i){
                  return (
                    <div key={i} style={{display:"flex",alignItems:"center",gap:10,
                      padding:"7px 0",borderBottom:"1px solid "+C.border,
                      color:C.muted,fontSize:12}}>
                      <span style={{color:C.acc,fontSize:10}}>&#9656;</span> {p}
                    </div>
                  );
                })}
              </div>

              <div style={{background:"#F59E0B10",border:"1px solid #F59E0B30",
                borderRadius:10,padding:16,marginBottom:20,fontSize:12}}>
                <span style={{color:"#F59E0B",fontWeight:700}}>Free Test: </span>
                <span style={{color:C.muted}}>{tool.freeTest}</span>
              </div>

              <div style={{display:"flex",gap:12}}>
                <button onClick={runPull} disabled={loading}
                  style={{background:loading?C.border:C.acc,
                    color:loading?C.muted:"#000",border:"none",borderRadius:8,
                    padding:"10px 24px",fontSize:12,fontWeight:700,
                    cursor:loading?"default":"pointer"}}>
                  {loading?"Pulling data…":hasPulled?"&#9654; Re-run Mock Pull":"&#9654; Run Mock Pull"}
                </button>
                {hasPulled&&(
                  <button onClick={function(){setActiveTab(ADAPTER_TAB.RAW);}}
                    style={{background:"transparent",color:C.muted,
                      border:"1px solid "+C.border,borderRadius:8,
                      padding:"10px 20px",fontSize:12,cursor:"pointer"}}>
                    View Raw JSON &#8594;
                  </button>
                )}
              </div>
            </div>
          )}

          {/* ── RAW RESPONSE TAB ── */}
          {activeTab===ADAPTER_TAB.RAW&&(
            <div style={{padding:24}}>
              <div style={{marginBottom:16}}>
                <div style={{fontSize:12,color:C.muted,marginBottom:4}}>
                  Actual response schema from {tool.label} API
                </div>
                <div style={{fontSize:11,color:"#F59E0B"}}>
                  CyberRx receives this &#8212; the normalization layer
                  strips it to a standard finding object
                </div>
              </div>
              <div style={{background:"#080D17",border:"1px solid "+C.border,
                borderRadius:10,padding:20,overflowX:"auto"}}>
                <pre style={{margin:0,fontSize:11,color:"#A8D8B9",lineHeight:1.7,
                  whiteSpace:"pre-wrap"}}>
                  {JSON.stringify(tool.rawResponse,null,2)}
                </pre>
              </div>
            </div>
          )}

          {/* ── NORMALIZED FINDINGS TAB ── */}
          {activeTab===ADAPTER_TAB.NORMALIZED&&(
            <div style={{padding:24}}>
              {!hasPulled?(
                <div style={{textAlign:"center",padding:"60px 20px",color:C.muted}}>
                  <div style={{fontSize:32,marginBottom:12}}>&#9672;</div>
                  <div>Run a mock pull to see normalized findings</div>
                </div>
              ):(
                <div>
                  <div style={{fontSize:11,color:C.muted,marginBottom:16}}>
                    Raw {tool.label} response &#8594; normalized finding
                    objects &#8594; mapped to CIS controls and compliance frameworks
                  </div>
                  {tool.normalized.map(function(f){
                    var sev    = SEV_CONFIG[f.severity]||SEV_CONFIG.info;
                    var isOpen = expandedFinding===f.id;
                    return (
                      <div key={f.id}
                        style={{background:C.card,
                          border:"1px solid "+(isOpen?C.acc+"50":C.border),
                          borderRadius:10,marginBottom:10,cursor:"pointer",
                          transition:"border 0.15s"}}
                        onClick={function(){
                          setExpandedFinding(isOpen?null:f.id);
                        }}>
                        <div style={{padding:"14px 18px",display:"flex",
                          alignItems:"center",gap:12}}>
                          <div style={{background:sev.bg,border:"1px solid "+sev.border,
                            borderRadius:4,padding:"2px 8px",fontSize:10,
                            color:sev.text,fontWeight:700,minWidth:70,
                            textAlign:"center"}}>
                            {sev.label}
                          </div>
                          <div style={{flex:1}}>
                            <div style={{fontSize:12,fontWeight:700,color:C.text}}>
                              {f.findingType}
                            </div>
                            <div style={{fontSize:11,color:C.muted,marginTop:2}}>
                              {f.id} &middot; {f.source} &middot;{" "}
                              {f.affectedAssets[0]}
                              {f.affectedAssets.length>1?" +"+( f.affectedAssets.length-1):""}
                            </div>
                          </div>
                          <div style={{textAlign:"right"}}>
                            <div style={{fontSize:11,color:C.acc}}>{f.cisControl}</div>
                            <div style={{fontSize:10,color:C.muted}}>{f.cisName}</div>
                          </div>
                          <div style={{color:C.muted,fontSize:14,marginLeft:8}}>
                            {isOpen?"&#x25B2;":"&#x25BC;"}
                          </div>
                        </div>

                        {isOpen&&(
                          <div style={{borderTop:"1px solid "+C.border,
                            padding:"16px 18px"}}>
                            <div style={{marginBottom:14}}>
                              <div style={{fontSize:10,color:C.muted,letterSpacing:2,
                                marginBottom:6}}>FINDING DETAIL</div>
                              <div style={{fontSize:12,color:C.text,lineHeight:1.7}}>
                                {f.detail}
                              </div>
                            </div>
                            <div style={{display:"grid",
                              gridTemplateColumns:"1fr 1fr",gap:12}}>
                              <div>
                                <div style={{fontSize:10,color:C.muted,
                                  letterSpacing:2,marginBottom:8}}>
                                  NORMALIZED OBJECT
                                </div>
                                <div style={{background:"#080D17",borderRadius:6,
                                  padding:12,fontSize:10,color:"#A8D8B9",
                                  lineHeight:1.8,fontFamily:"monospace"}}>
                                  <div>
                                    <span style={{color:C.muted}}>id: </span>{f.id}
                                  </div>
                                  <div>
                                    <span style={{color:C.muted}}>source: </span>{f.source}
                                  </div>
                                  <div>
                                    <span style={{color:C.muted}}>severity: </span>
                                    <span style={{color:sev.text}}>{f.severity}</span>
                                  </div>
                                  <div>
                                    <span style={{color:C.muted}}>count: </span>{f.count}
                                  </div>
                                  <div>
                                    <span style={{color:C.muted}}>cisControl: </span>{f.cisControl}
                                  </div>
                                  <div>
                                    <span style={{color:C.muted}}>cisName: </span>{f.cisName}
                                  </div>
                                </div>
                              </div>
                              <div>
                                <div style={{fontSize:10,color:C.muted,
                                  letterSpacing:2,marginBottom:8}}>
                                  FRAMEWORK MAPPING
                                </div>
                                {(f.frameworks||[]).length===0?(
                                  <div style={{fontSize:11,color:C.muted,padding:12}}>
                                    Internal tracking only
                                  </div>
                                ):(
                                  (f.frameworks||[]).map(function(fw,i){
                                    return (
                                      <div key={i} style={{background:C.surface,
                                        border:"1px solid "+C.border,
                                        borderRadius:5,padding:"5px 10px",
                                        fontSize:11,color:C.text,marginBottom:6}}>
                                        {fw}
                                      </div>
                                    );
                                  })
                                )}
                              </div>
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {/* ── CIS CONTROL SCORE IMPACT TAB ── */}
          {activeTab===ADAPTER_TAB.MAPPING&&(
            <div style={{padding:24}}>
              <div style={{marginBottom:20}}>
                <div style={{fontSize:16,fontWeight:700,marginBottom:4}}>
                  CIS Control Score Impact
                </div>
                <div style={{fontSize:11,color:C.muted}}>
                  Aggregated across all connected sources &middot; Projected improvement when findings are remediated
                </div>
              </div>

              {Object.keys(pulled).length===0?(
                <div style={{textAlign:"center",padding:"60px 20px",color:C.muted}}>
                  <div>Connect at least one source to see control scores</div>
                </div>
              ):(
                Object.entries(CIS_SCORES).map(function(cisEntry){
                  var id   = cisEntry[0];
                  var ctrl = cisEntry[1];
                  var relatedFindings = cisImpact[id]||[];
                  var hasFindings = relatedFindings.length>0;
                  return (
                    <div key={id} style={{background:C.card,
                      border:"1px solid "+(hasFindings?ctrl.color+"40":C.border),
                      borderRadius:10,padding:18,marginBottom:12}}>
                      <div style={{display:"flex",alignItems:"center",gap:16,
                        marginBottom:hasFindings?14:0}}>
                        <div style={{minWidth:52,textAlign:"center"}}>
                          <div style={{fontSize:22,fontWeight:700,
                            color:ctrl.score<65?"#EF4444":ctrl.score<80?"#F59E0B":"#10B981"}}>
                            {ctrl.score}
                          </div>
                          <div style={{fontSize:9,color:C.muted,marginTop:2}}>
                            CURRENT
                          </div>
                        </div>
                        <div style={{flex:1}}>
                          <div style={{display:"flex",justifyContent:"space-between",
                            marginBottom:6}}>
                            <div style={{fontSize:12,fontWeight:700}}>
                              {id} &#8212; {ctrl.name}
                            </div>
                            {hasFindings&&(
                              <div style={{fontSize:11,color:C.acc}}>
                                +{ctrl.impact} pts if resolved
                              </div>
                            )}
                          </div>
                          <div style={{background:C.border,borderRadius:4,
                            height:6,overflow:"hidden"}}>
                            <div style={{width:ctrl.score+"%",height:"100%",
                              background:ctrl.score<65?"#EF4444":ctrl.score<80?"#F59E0B":"#10B981",
                              borderRadius:4,transition:"width 0.4s"}}/>
                          </div>
                        </div>
                        {hasFindings&&(
                          <div style={{minWidth:52,textAlign:"center",
                            background:C.accDim,borderRadius:6,padding:"4px 8px"}}>
                            <div style={{fontSize:16,fontWeight:700,color:C.acc}}>
                              {ctrl.score+ctrl.impact}
                            </div>
                            <div style={{fontSize:9,color:C.acc}}>PROJECTED</div>
                          </div>
                        )}
                      </div>
                      {hasFindings&&(
                        <div style={{borderTop:"1px solid "+C.border,paddingTop:12}}>
                          <div style={{fontSize:10,color:C.muted,letterSpacing:2,
                            marginBottom:8}}>FINDINGS AFFECTING THIS CONTROL</div>
                          {relatedFindings.map(function(f){
                            var sev=SEV_CONFIG[f.severity]||SEV_CONFIG.info;
                            return (
                              <div key={f.id} style={{display:"flex",
                                alignItems:"center",gap:10,padding:"6px 0",
                                borderBottom:"1px solid "+C.border+"40",fontSize:11}}>
                                <span style={{color:sev.text,fontSize:9}}>&#9679;</span>
                                <span style={{color:C.muted}}>{f.source}</span>
                                <span style={{color:C.text,flex:1}}>{f.findingType}</span>
                                <span style={{color:sev.text}}>{sev.label}</span>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })
              )}
            </div>
          )}

        </div>
      </div>
    </div>
  );
}

