// ── Helper functions ─────────────────────────────────────────────────────────
function modAvgSc(cs) {
  var total = 0;
  for (var i=0;i<cs.length;i++) { total += (MOD_CH[cs[i]] ? MOD_CH[cs[i]].s : 50); }
  return Math.round(total / cs.length);
}
function modPassThru(s) {
  return s>=85?5:s>=75?13:s>=65?24:s>=55?36:s>=45?50:s>=35?65:80;
}
function modRClr(p)  { return p>=65?"#F05050":p>=45?"#F07830":p>=28?"#E8B830":"#18C080"; }
function modSClr(s)  { return s>=80?"#18C080":s>=65?"#E8B830":s>=50?"#F07830":"#F05050"; }
function modCjScore(a) {
  return Math.round((a.sc.sensitivity+a.sc.impact+a.sc.regulatory+a.sc.exposure+(a.sc.dependencies*5))/5.4);
}
function modAncestors(targetId) {
  var all = ATK_EDGES.concat(ATK_CJE);
  var visited = {};
  var q = [targetId];
  while (q.length > 0) {
    var cur = q.shift();
    for (var i=0;i<all.length;i++) {
      if (all[i].t === cur && !visited[all[i].f]) {
        visited[all[i].f] = true;
        q.push(all[i].f);
      }
    }
  }
  return visited;
}
function modMapEdgePt(src, tgt, isOut) {
  var dx = tgt.cx - src.cx; var dy = tgt.cy - src.cy;
  var BW = 65; var BH = 27;
  if (Math.abs(dx) >= Math.abs(dy)) {
    if (isOut) { return dx>0 ? {x:src.cx+BW,y:src.cy} : {x:src.cx-BW,y:src.cy}; }
    return dx>0 ? {x:tgt.cx-BW,y:tgt.cy} : {x:tgt.cx+BW,y:tgt.cy};
  }
  if (isOut) { return dy>0 ? {x:src.cx,y:src.cy+BH} : {x:src.cx,y:src.cy-BH}; }
  return dy>0 ? {x:tgt.cx,y:tgt.cy-BH} : {x:tgt.cx,y:tgt.cy+BH};
}

