// ─── Exposure Column Chart component ─────────────────────────────────────────
// Financial baseline for each exposure category
var EXPOSURE_BASELINES = {
  breach:      {base:"surplus",  label:"% of Statutory Surplus", color:"#3B9EFF"},
  interruption:{base:"ibnr",     label:"% of Claims Reserves",   color:"#0891B2"},
  regulatory:  {base:"surplus",  label:"% of Statutory Surplus", color:"#3B9EFF"},
  fraud:       {base:"surplus",  label:"% of Statutory Surplus", color:"#3B9EFF"},
  reputation:  {base:"surplus",  label:"% of Statutory Surplus", color:"#3B9EFF"},
  legal:       {base:"surplus",  label:"% of Statutory Surplus", color:"#3B9EFF"},
  recovery:    {base:"itbudget", label:"% of IT Budget",          color:"#0FBB80"},
};

function zoneColor(pct) {
  if (pct >= 10) { return "#EF4545"; }
  if (pct >= 5)  { return "#F5A623"; }
  if (pct >= 2)  { return "#F5E642"; }
  return "#0FBB80";
}

function ExposureColumnChart(props) {
  var onSelect   = props.onSelect;
  var selectedId = props.selectedId;
  var surplus    = props.surplus  > 0 ? props.surplus   : 2500e6;
  var ibnr       = props.ibnr     > 0 ? props.ibnr      : 1500e6;
  var itBudget   = props.itBudget > 0 ? props.itBudget  : 300e6;

  function getBase(catId) {
    var b = EXPOSURE_BASELINES[catId];
    if (!b) { return {val:surplus, label:"% of Surplus", bcolor:"#3B9EFF"}; }
    if (b.base==="ibnr")     { return {val:ibnr,     label:b.label, bcolor:b.color}; }
    if (b.base==="itbudget") { return {val:itBudget, label:b.label, bcolor:b.color}; }
    return {val:surplus, label:b.label, bcolor:b.color};
  }

  // Compute pct for each category
  var barsData = EXPOSURE_HIERARCHY.map(function(cat){
    var base = getBase(cat.id);
    var pct  = Math.round(cat.total*1e6 / base.val * 100 * 10) / 10;
    return {cat:cat, pct:pct, base:base, zcolor:zoneColor(pct)};
  });

  var maxPct = Math.max.apply(null, barsData.map(function(d){return d.pct;}));
  var barW = 64; var gap = 14; var chartH = 220; var labelH = 60;
  var totalW = barsData.length * (barW+gap);

  return (
    <div style={{overflowX:"auto",marginBottom:6}}>
      <svg width={totalW} height={chartH+labelH+16}
        viewBox={"0 0 "+totalW+" "+(chartH+labelH+16)}
        style={{display:"block",minWidth:totalW}}>

        {/* Zone bands */}
        {[
          {threshold:10, label:">10% Critical",  color:"#EF454508"},
          {threshold:5,  label:"5-10% High",     color:"#F5A62306"},
          {threshold:2,  label:"2-5% Moderate",  color:"#F5E64204"},
        ].map(function(zone){
          var y = Math.round((1 - zone.threshold/maxPct) * (chartH-12)) + 10;
          if (y < 10 || y > chartH) { return null; }
          return (
            <g key={zone.threshold}>
              <line x1={0} y1={y} x2={totalW} y2={y}
                stroke={zoneColor(zone.threshold)} strokeWidth="1"
                strokeDasharray="5 3" opacity="0.5"/>
              <text x={totalW-3} y={y-3} textAnchor="end"
                fill={zoneColor(zone.threshold)} fontSize={7} opacity="0.7">
                {zone.threshold+"%"}
              </text>
            </g>
          );
        })}

        {/* Bars */}
        {barsData.map(function(d, i){
          var cat    = d.cat;
          var x      = i*(barW+gap) + gap/2;
          var barH   = Math.max(6, Math.round(d.pct/maxPct*(chartH-12)));
          var y      = chartH + 10 - barH;
          var isSel  = selectedId === cat.id;

          return (
            <g key={cat.id}
              onClick={function(){onSelect(isSel?null:cat.id);}}
              style={{cursor:"pointer"}}>

              {/* Main bar — colored by risk zone */}
              <rect x={x} y={y} width={barW} height={barH}
                fill={d.zcolor} opacity={isSel?1:0.78} rx={4}/>

              {/* Thin accent strip at bottom in category color */}
              <rect x={x} y={y+barH-5} width={barW} height={5}
                fill={cat.color} opacity={0.6} rx="0 0 4 4"/>

              {/* Selection glow */}
              {isSel&&(
                <rect x={x-2} y={y-2} width={barW+4} height={barH+2}
                  fill="none" stroke={d.zcolor} strokeWidth="2.5" rx={5}/>
              )}

              {/* % label on top */}
              <text x={x+barW/2} y={y-5} textAnchor="middle"
                fill={isSel?d.zcolor:"#ccc"} fontSize={isSel?11:10}
                fontWeight={isSel?"bold":"normal"}>
                {d.pct+"%"}
              </text>

              {/* Dollar value inside bar */}
              {barH>22&&(
                <text x={x+barW/2} y={y+barH/2+4} textAnchor="middle"
                  fill="rgba(255,255,255,0.9)" fontSize={8} fontWeight="700">
                  {"$"+cat.total+"M"}
                </text>
              )}

              {/* Icon + label below */}
              <text x={x+barW/2} y={chartH+24} textAnchor="middle" fontSize={14}>
                {cat.icon}
              </text>
              {(function(){
                var words = cat.label.split(" ");
                var lines2=[],cur="";
                words.forEach(function(w){
                  if((cur+" "+w).trim().length>11&&cur){lines2.push(cur);cur=w;}
                  else{cur=cur?(cur+" "+w):w;}
                });
                if(cur){lines2.push(cur);}
                return lines2.slice(0,2).map(function(l2,li){
                  return (
                    <text key={li} x={x+barW/2} y={chartH+38+li*11}
                      textAnchor="middle"
                      fill={isSel?d.zcolor:C.muted}
                      fontSize={9} fontWeight={isSel?700:400}>{l2}</text>
                  );
                });
              })()}

              {/* Baseline label below icon */}
              <text x={x+barW/2} y={chartH+labelH+4} textAnchor="middle"
                fill={d.base.bcolor} fontSize={7} opacity="0.7">
                {d.base.label.split(" ").slice(0,2).join(" ")}
              </text>
            </g>
          );
        })}
      </svg>

      {/* Baseline key */}
      <div style={{display:"flex",gap:12,padding:"6px 4px",flexWrap:"wrap"}}>
        {[
          {c:"#3B9EFF",l:"vs Statutory Surplus"},
          {c:"#0891B2",l:"vs Claims Reserves (IBNR)"},
          {c:"#0FBB80",l:"vs IT Budget"},
        ].map(function(k){
          return (
            <div key={k.l} style={{display:"flex",gap:4,alignItems:"center"}}>
              <div style={{width:8,height:3,background:k.c,borderRadius:1}}/>
              <span style={{color:C.muted,fontSize:8}}>{k.l}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ExposureModelCard(props) {
  var go       = props.go;
  var surplus  = props.surplus  || 0;
  var ibnr     = props.ibnr     || 0;
  var itBudget = props.itBudget || 0;
  var phiRecs  = props.phiRecords || 3000000;
  var revenue  = props.revenue  || 4200e6;

  // Derived baselines (mirroring CFODash logic)
  var surplusB   = surplus  > 0 ? surplus  : 2500e6;
  var ibnrB      = ibnr     > 0 ? ibnr     : 1500e6;
  var itB        = itBudget > 0 ? itBudget : 300e6;

  // Exposure category estimates from org data
  var phiNotifCost  = phiRecs * 35;
  var breachRespM   = Math.round((phiNotifCost + 15e6 + 22e6 + 4.5e6 + 8.5e6 + 12e6 + Math.min(250e6, phiRecs*60))/1e6);
  var regulatoryM   = Math.round(surplusB * 0.138 / 1e6);
  var fraudM        = Math.round((revenue*0.03 + phiRecs*22) / 1e6);
  var reputM        = Math.round(revenue * 0.04 / 1e6);
  var interruptM    = Math.round((revenue * 0.0137 + 55e6) / 1e6);
  var legalM        = 56;
  var recoveryM     = Math.round(itB * 0.037 / 1e6);

  // Percentage of relevant baseline
  var capitalPct    = Math.round((breachRespM+regulatoryM+reputM+fraudM+legalM)*1e6/surplusB*100*10)/10;
  var claimsPct     = Math.round(interruptM*1e6/ibnrB*100*10)/10;
  var itPct         = Math.round(recoveryM*1e6/itB*100*10)/10;

  var _s0=useState(null); var selCat=_s0[0];   var setSelCat=_s0[1];
  var _s1=useState(null); var selChild=_s1[0]; var setSelChild=_s1[1];

  var totalGross = EXPOSURE_HIERARCHY.reduce(function(s,c){return s+c.total;},0); var totalGross2 = props.grossExpM || totalGross;
  var cat   = selCat   ? EXPOSURE_HIERARCHY.find(function(c){return c.id===selCat;})   : null;
  var child = (selChild&&cat) ? cat.children.find(function(c){return c.id===selChild;}) : null;

  // Compute risk metrics for header summary
  var surpBase  = surplus  > 0 ? surplus  : 2500e6;
  var ibnrBase  = ibnr     > 0 ? ibnr     : 1500e6;
  var itBase    = itBudget > 0 ? itBudget : 300e6;

  var capitalImpact  = (285+346+259+78+340) * 1e6;   // Breach+Reg+Rep+Legal+Fraud
  var claimsImpact   = 217e6;                          // Interruption
  var capitalPct     = Math.round(capitalImpact/surpBase*100*10)/10;
  var claimsPct      = Math.round(claimsImpact/ibnrBase*100*10)/10;
  var itPct          = Math.round(11e6/itBase*100*10)/10;

  return (
    <Card style={{marginBottom:14}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:12}}>
        <div>
          <SH label="Estimated Cybersecurity Exposure Model"/>
          <div style={{color:C.muted,fontSize:11}}>
            Each category benchmarked against its relevant financial reserve
          </div>
        </div>
        <div style={{textAlign:"right",flexShrink:0}}>
          <div style={{color:"#EF4545",fontSize:22,fontWeight:800,fontFamily:"monospace"}}>
            {"$"+totalGross+"M"}
          </div>
          <div style={{color:C.muted,fontSize:9}}>Total Gross Exposure</div>
        </div>
      </div>

      {/* 3 impact summary cards — click for methodology */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:14}}>
        {[
          {label:"Capital at Risk",      pct:capitalPct, base:"of $"+fmtExp(surplusB/1e6)+" Surplus",
           sub:"Breach ($"+(Math.round(breachRespM))+"M) + Reg ($"+regulatoryM+"M) + Rep ($"+reputM+"M) + Fraud ($"+fraudM+"M) + Legal ($"+legalM+"M)",
           color:zoneColor(capitalPct), tab:"rbc",
           methodology:"Sum of capital-impacting categories vs statutory surplus. PHI records: "+fmtNum(phiRecs)+". Breach notification: $35/record (OCR standard)."},
          {label:"Claims Reserve Stress",pct:claimsPct,  base:"of $"+fmtExp(ibnrB/1e6)+" IBNR",
           sub:"Business Interruption: $"+interruptM+"M ("+fmtExp(revenue/1e6)+" rev × 1.37% + CMS sanctions)",
           color:zoneColor(claimsPct), tab:"scenarios",
           methodology:"Claims reserve impact from NASCO/HealthEdge outage. Revenue × daily claims rate × estimated downtime days."},
          {label:"IT Budget Draw",       pct:itPct,      base:"of $"+fmtExp(itB/1e6)+" IT Budget",
           sub:"System rebuild + security uplift: $"+recoveryM+"M",
           color:zoneColor(itPct), tab:"rosi",
           methodology:"Recovery cost = 3.7% of IT budget per industry benchmark (Ponemon 2024). Includes DR restoration and security uplift."},
        ].map(function(s){
          return (
            <div key={s.label}
              onClick={function(){setCfTab(s.tab);}}
              style={{background:s.color+"12",border:"1px solid "+s.color+"35",
                borderRadius:9,padding:"10px 12px",cursor:"pointer",
                textAlign:"center"}}>
              <div style={{color:s.color,fontSize:22,fontWeight:800,fontFamily:"monospace",
                marginBottom:2}}>{s.pct+"%"}</div>
              <div style={{color:C.text,fontSize:10,fontWeight:700,marginBottom:1}}>{s.label}</div>
              <div style={{color:s.color,fontSize:9,fontWeight:600,marginBottom:2}}>
                {s.base}
              </div>
              <div style={{color:C.muted,fontSize:8,lineHeight:1.4,marginBottom:3}}>{s.sub}</div>
              <div style={{color:s.color,fontSize:7,background:s.color+"10",borderRadius:3,
                padding:"1px 6px",display:"inline-block"}}>click for detail</div>
            </div>
          );
        })}
      </div>

      {/* Column chart */}
      <ExposureColumnChart selectedId={selCat}
        surplus={surpBase} ibnr={ibnrBase} itBudget={itBase}
        onSelect={function(id){setSelCat(id);setSelChild(null);}}/>

      {/* Legend chips */}
      <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:10,marginTop:4}}>
        {EXPOSURE_HIERARCHY.map(function(c){
          var isActive = selCat===c.id;
          return (
            <button key={c.id}
              onClick={function(){setSelCat(isActive?null:c.id);setSelChild(null);}}
              style={{display:"flex",gap:4,alignItems:"center",padding:"3px 10px",
                background:isActive?c.color+"18":C.dim,
                border:"1px solid "+(isActive?c.color+"50":C.border),
                borderRadius:20,cursor:"pointer"}}>
              <span style={{fontSize:10}}>{c.icon}</span>
              <span style={{color:isActive?c.color:C.muted,fontSize:9,fontWeight:isActive?700:400}}>
                {c.label}
              </span>
              <span style={{color:c.color,fontSize:9,fontWeight:800,fontFamily:"monospace"}}>
                {"$"+c.total+"M"}
              </span>
            </button>
          );
        })}
      </div>

      {/* Category detail */}
      {cat&&(
        <div style={{borderTop:"1px solid "+cat.color+"25",paddingTop:12}}>
          <div style={{display:"flex",gap:10,alignItems:"flex-start",marginBottom:10}}>
            <span style={{fontSize:24,flexShrink:0}}>{cat.icon}</span>
            <div style={{flex:1}}>
              <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:4,flexWrap:"wrap"}}>
                <span style={{color:cat.color,fontSize:14,fontWeight:800}}>{cat.label}</span>
                <span style={{color:cat.color,fontSize:13,fontWeight:800,fontFamily:"monospace",
                  background:cat.color+"14",borderRadius:5,padding:"2px 10px"}}>
                  {"$"+cat.total+"M"}
                </span>
                {(function(){
                  var b = EXPOSURE_BASELINES[cat.id];
                  var baseVal = b && b.base==="ibnr" ? ibnrBase : b && b.base==="itbudget" ? itBase : surpBase;
                  var pct     = Math.round(cat.total*1e6/baseVal*100*10)/10;
                  var zc      = zoneColor(pct);
                  var bl      = b ? b.label : "% of Surplus";
                  return (
                    <span style={{color:zc,fontSize:10,fontWeight:700,background:zc+"14",
                      borderRadius:4,padding:"2px 8px"}}>
                      {pct+"% "+bl}
                    </span>
                  );
                })()}
              </div>
              <p style={{color:C.text,fontSize:12,lineHeight:1.7,margin:"0 0 10px"}}>
                {cat.summary}
              </p>
            </div>
          </div>

          {/* Children grid */}
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,marginBottom:10}}>
            {cat.children.map(function(ch){
              var isSel = selChild===ch.id;
              return (
                <div key={ch.id}
                  onClick={function(){setSelChild(isSel?null:ch.id);}}
                  style={{background:isSel?ch.color+"14":C.bg,
                    border:"1.5px solid "+(isSel?ch.color+"50":C.border),
                    borderRadius:9,padding:"10px 12px",cursor:"pointer"}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:4}}>
                    <span style={{color:isSel?ch.color:C.text,fontSize:11,fontWeight:isSel?700:500,
                      flex:1,lineHeight:1.3}}>{ch.label}</span>
                    <span style={{color:ch.color,fontSize:12,fontWeight:800,fontFamily:"monospace",
                      marginLeft:8,flexShrink:0}}>{"$"+ch.val.toFixed(1)+"M"}</span>
                  </div>
                  <div style={{height:3,background:C.dim,borderRadius:2,overflow:"hidden"}}>
                    <div style={{width:Math.round(ch.val/cat.total*100)+"%",
                      height:"100%",background:ch.color}}/>
                  </div>
                  <div style={{color:C.muted,fontSize:9,marginTop:2}}>
                    {Math.round(ch.val/cat.total*100)}% of {cat.label}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Child write-up */}
          {child&&(
            <div style={{background:child.color+"08",border:"1.5px solid "+child.color+"30",
              borderRadius:10,padding:"12px 16px",marginBottom:10}}>
              <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:8}}>
                <div style={{width:10,height:10,borderRadius:"50%",background:child.color,flexShrink:0}}/>
                <span style={{color:child.color,fontSize:13,fontWeight:800}}>{child.label}</span>
                <span style={{color:child.color,fontSize:13,fontWeight:800,fontFamily:"monospace",
                  marginLeft:"auto"}}>${child.val.toFixed(1)}M</span>
              </div>
              <p style={{color:C.text,fontSize:12,lineHeight:1.8,margin:"0 0 10px"}}>{child.write}</p>
              <div style={{display:"flex",gap:8}}>
                <Btn onClick={function(){go("execution");}} primary small>Route to Execution</Btn>
                <Btn onClick={function(){go("cro");}} small>View Controls</Btn>
                <button onClick={function(){setSelChild(null);}}
                  style={{background:"transparent",border:"1px solid "+C.border,color:C.muted,
                    borderRadius:6,padding:"3px 10px",cursor:"pointer",fontSize:10}}>
                  Close
                </button>
              </div>
            </div>
          )}
          <Btn onClick={function(){go("boarddash");}} small>Board Briefing →</Btn>
        </div>
      )}
    </Card>
  );
}

